      "author": "未知",
      "source": "https://www.instagram.com/reel/DUA81J-jy5p/?igsh=MjlmZ2Q4ZGphNDVi",
      "ingredients": "### 主料\n- 港式蘿蔔糕：1 大塊（約 400 克，切成立體方塊）\n- 雞蛋：2 顆（打散成蛋液）\n- 綠豆芽（可去頭尾做成銀芽）：1 大把\n- 麵粉（或太白粉/生粉）：1-2 大匙（用以裹粉防沾）",
      "summary": "XO醬蛋炒蘿蔔糕 過年吃不完的煎蘿蔔糕，或是想給平淡的港式蘿蔔糕來點華麗變身？這道由名廚王輔立傳授的「XO醬蛋炒蘿蔔糕」是絕對不能錯過的避坑美味。將蘿蔔糕煎到外脆內軟，再以香氣濃郁的 XO 醬與豐富辛香料爆炒，最後裹上嫩滑的蛋液，搭配清脆爽口的豆芽菜。原本便宜的蘿蔔糕瞬間升級為高級港式茶餐廳的名菜，...",
      "content": "# XO醬蛋炒蘿蔔糕\n\n過年吃不完的煎蘿蔔糕，或是想給平淡的港式蘿蔔糕來點華麗變身？這道由名廚王輔立傳授的「XO醬蛋炒蘿蔔糕」是絕對不能錯過的避坑美味。將蘿蔔糕煎到外脆內軟，再以香氣濃郁的 XO 醬與豐富辛香料爆炒，最後裹上嫩滑的蛋液，搭配清脆爽口的豆芽菜。原本便宜的蘿蔔糕瞬間升級為高級港式茶餐廳的名菜，鮮甜香辣、多層次的口感讓人大呼過癮！\n\n## 🥣 食材清單\n\n### 主料\n- 港式蘿蔔糕：1 大塊（約 400 克，切成立體方塊）\n- 雞蛋：2 顆（打散成蛋液）\n- 綠豆芽（可去頭尾做成銀芽）：1 大把\n- 麵粉（或太白粉/生粉）：1-2 大匙（用以裹粉防沾）\n\n### 🧂 爆香辛香料\n- 洋蔥：1/4 顆（切碎）\n- 蒜頭：3-4 瓣（切蒜末）\n- 蔥：2 根（切蔥花，蔥白與蔥綠分開）\n- 辣椒：1 根（切斜片）\n- 香菜：適量（切碎，香菜莖與香菜葉分開）\n\n### 🥣 醬燒調味料\n- XO 醬：1.5 - 2 大匙\n- 蠔油：1 大匙\n- 醬油：1 大匙\n- 白胡椒粉：適量\n- 砂糖：0.5 小匙\n- 米酒：1 大匙（嗆鍋用）\n- 香油：少許\n\n## 🍳 製作步驟\n\n1. **切塊裹粉（防沾防碎關鍵）**：\n   將蘿蔔糕切成約 2 - 2.5 公分的立體方塊。在表面均勻撒上一層薄薄的麵粉，輕輕抖動均勻抓裹。\n   > [!TIP]\n   > 蘿蔔糕在表面拍上一層乾麵粉或太白粉，下油鍋時能極速鎖住內部水分並定型。這不僅能防止蘿蔔糕沾鍋，還能有效防止翻炒時蘿蔔糕破碎糊爛，且能煎出更加香脆的「恰恰」外殼。\n2. **煎至金黃**：\n   平底鍋倒入適量油，開中火，放入蘿蔔糕塊，慢慢煎烤至每一面都呈現「金黃微焦（恰恰）」的酥脆狀態，隨後盛出控油備用。\n3. **爆香辛香料**：\n   原鍋保留少許底油，放入洋蔥碎、蔥白、蒜末以及香菜莖碎，以中小火煸炒出濃郁的辛香味。\n4. **醬汁翻炒與XO醬**：\n   將煎好的蘿蔔糕重新倒入鍋中，加入蠔油 1 大匙、醬油 1 大匙、白胡椒粉、糖，大火翻炒均勻使蘿蔔糕入底味。隨後加入 1.5 - 2 大匙 XO 醬，快速翻炒出乾醬香。\n5. **蛋液包覆與爽脆配菜**：\n   將打散的蛋液**均勻淋在蘿蔔糕周圍**。在蛋液呈現半熟狀態時，立即放入豆芽菜、辣椒片，轉大火翻炒，讓半熟蛋包裹在每塊蘿蔔糕表面。\n6. **嗆香與盛盤**：\n   起鍋前沿著鍋邊淋入 1 大匙米酒嗆香，加入蔥綠與香菜葉，淋上少許香油，大火快速翻炒 2 下（讓豆芽菜保持斷生脆口），即可盛盤享用！\n\n---\n\n## 💡 廚神小撇步\n- **如何把蛋炒得有包裹感？**：蛋液淋在蘿蔔糕上後，不要立刻瘋狂翻炒。等約 3 秒鐘讓底部蛋液稍微凝固，再輕輕翻動，這樣蛋皮就會以「半包覆」的姿態黏附在蘿蔔糕上，吃起來既能吃到蘿蔔糕的脆，又能吃到嫩蛋的口感。\n- **XO醬的鹹度控制**：XO醬本身帶有鹹味和海鮮的甘甜。在步驟 4 調味時，先加適量的醬油與蠔油，若使用的 XO 醬本身偏鹹，鹽巴的量可直接省略，並加少許糖來柔和整體的辣度與鹹度。",
