      "author": "未知",
      "source": "https://www.instagram.com/reel/DTDBLY9gW0f/?igsh=MTc4bjhyOXJudno4YQ==",
      "ingredients": "### 主料\n- 去骨帶皮雞腿肉：300 克（切成一口大小）\n- 白蘿蔔：1 根（約 400 克，切滾刀塊）\n- 乾香菇：6 - 8 朵（以溫水泡發 15 分鐘，**香菇水務必保留**）",
      "summary": "一鍋到底香菇雞肉燜蘿蔔 這是一道溫暖、治癒且鮮美無比的冬日家常燉菜——「一鍋到底香菇雞肉燜蘿蔔」。白蘿蔔若是直接水煮，常會顯得平淡無奇且帶有生澀的蘿蔔氣味。本食譜為您解密大廚級的「雞油煎蘿蔔」與「香菇水鮮味乘數效應」。先以冷鍋不下油逼出雞皮本身的油脂，將白蘿蔔煎至微焦黃以消除生辣，再以蘊含高濃度天然...",
      "content": "# 一鍋到底香菇雞肉燜蘿蔔\n\n這是一道溫暖、治癒且鮮美無比的冬日家常燉菜——「一鍋到底香菇雞肉燜蘿蔔」。白蘿蔔若是直接水煮，常會顯得平淡無奇且帶有生澀的蘿蔔氣味。本食譜為您解密大廚級的「雞油煎蘿蔔」與「香菇水鮮味乘數效應」。先以冷鍋不下油逼出雞皮本身的油脂，將白蘿蔔煎至微焦黃以消除生辣，再以蘊含高濃度天然呈鮮物質的香菇水慢火燜煮，最後利用水澱粉勾薄芡完美掛汁，讓您一連多吃好幾碗白飯！\n\n## 🥣 食材清單\n\n### 主料\n- 去骨帶皮雞腿肉：300 克（切成一口大小）\n- 白蘿蔔：1 根（約 400 克，切滾刀塊）\n- 乾香菇：6 - 8 朵（以溫水泡發 15 分鐘，**香菇水務必保留**）\n\n### 🧂 調味與勾芡\n- 薑片：3 片\n- 蒜頭：15 克（切蒜粒）\n- 醬油（生抽）：1.5 大匙\n- 蠔油：1 大匙\n- 砂糖：1 茶匙\n- 米酒：1 大匙\n- 太白粉（或玉米澱粉）：1 小匙（調成生粉水/水澱粉用）\n\n---\n\n## 🍳 製作步驟\n\n1. **雞腿肉無油乾煎（逼出天然雞油）**：\n   不沾炒鍋內**不加任何油**。直接將切塊的雞腿肉**「皮朝下」放入冷鍋中**。開中火慢煎，將雞皮底下的豐富脂肪慢慢逼出，煎至雞皮金黃酥脆後，翻面煎 1 分鐘，盛出備用。\n   > [!TIP]\n   > 雞油含有豐富的揮發性肉類香氣化合物，用它來代替植物油煎蘿蔔，能賦予白蘿蔔極其醇厚的肉香與滑順感。\n2. **雞油煎蘿蔔（焦糖化去苦）**：\n   利用鍋底殘留的黃亮雞油，放入白蘿蔔塊。開中火慢煎，**將白蘿蔔煎到兩面邊緣稍微呈現微焦黃上色**，撈出備用。\n   > [!IMPORTANT]\n   > **煎蘿蔔的物理去苦科學**：白蘿蔔中的天然糖分（葡萄糖、果糖）在雞油的熱傳導下，會在表面產生微弱的「焦糖化反應」，這不僅能徹底消除白蘿蔔特有的生辣氣味與苦澀，還能在表面形成保護層，使其在後續 15 分鐘的燉煮中不至於散架糊爛。\n3. **爆香香料**：\n   原鍋中放入薑片、蒜粒與泡發好切半的乾香菇，以中火煸炒 1 分鐘，直到香菇散發出濃郁香氣。\n4. **鮮味大團圓（香菇水鮮味乘數）**：\n   依序倒入煎好的雞腿肉、白蘿蔔。加入醬油 1.5 大匙、蠔油 1 大匙、糖 1 茶匙與米酒 1 大匙翻炒均勻。隨後**倒入泡香菇的「香菇水」**（量需剛好沒過食材大半，不夠可補少許水），大火燒開。\n   > [!IMPORTANT]\n   > **香菇水增鮮的化學效應**：乾香菇富含「鳥苷酸（Guanylate）」，雞肉則富含「肌苷酸（Inosinate）」。當這兩種呈味核苷酸相遇時，會在舌頭的味覺感受器上產生驚人的「鮮味乘數效應（Umami Synergy）」，其鮮美度能以幾何級數提高。因此利用香菇水燜煮，能讓整鍋燉菜不需加任何味精便鮮甜無比。\n5. **小火燜煮 15 分鐘**：\n   大火煮滾後，轉小火，蓋上鍋蓋**慢火燜煮 15 分鐘**，直至白蘿蔔完全軟爛入味。\n6. **水澱粉勾芡掛汁（掛味關鍵步）**：\n   打開鍋蓋，此時湯汁已變濃。將 1 小匙太白粉與 2 大匙水調勻，沿鍋邊淋入，大火翻炒 10 秒至湯汁收稠，讓鮮美的焦糖色醬汁均勻地裹在每一塊白蘿蔔和雞肉上，即可盛盤！",
