      "ingredients": "### 主料\n* 杏鮑菇 4-5 根\n* 薑片 適量\n* 蒜頭 適量（素食者可去蒜）\n* 紅辣椒 1 根（配色用）\n* 九層塔 1 大把\n* 蔥段 適量",
      "summary": "三杯杏鮑菇 經典的三杯風味蔬食版！將厚切杏鮑菇劃上花刀，煎至金黃微焦，多汁的菇肉吸滿胡麻油、醬油與九層塔的濃郁香氣，口感彈牙飽滿，比肉還好吃！ 🥣 食材清單 主料 杏鮑菇 45 根 薑片 適量 蒜頭 適量（素食者可去蒜） 紅辣椒 1 根（配色用） 九層塔 1 大把 蔥段 適量 調味料（醬汁） 糖 5...",
      "content": "# 三杯杏鮑菇\n\n經典的三杯風味蔬食版！將厚切杏鮑菇劃上花刀，煎至金黃微焦，多汁的菇肉吸滿胡麻油、醬油與九層塔的濃郁香氣，口感彈牙飽滿，比肉還好吃！\n\n## 🥣 食材清單\n\n### 主料\n* 杏鮑菇 4-5 根\n* 薑片 適量\n* 蒜頭 適量（素食者可去蒜）\n* 紅辣椒 1 根（配色用）\n* 九層塔 1 大把\n* 蔥段 適量\n\n### 調味料（醬汁）\n* 糖 5g\n* 米酒 100g\n* 醬油（或湯布院醬油） 15g\n* 香菇素蠔油 30g\n* 黑麻油（胡麻油） 15g + 起鍋少許\n* 橄欖油 適量\n\n## 🍳 製作步驟\n\n1. **改刀處理**：將杏鮑菇切成約一根手指寬（2 公分）的厚圓片，正反兩面劃上記號般的菱格紋花刀以利入味與熟透。\n2. **冷油煸薑與煎菇**：起鍋倒入橄欖油與黑麻油（比例 1:1），放入薑片開小火慢慢冷油煸香至邊緣微微捲曲。倒入杏鮑菇厚片，先不要急著翻鍋，靜置煎至正反兩面金黃上色。\n3. **下糖與燒醬**：撒上糖翻炒，使杏鮑菇表面呈現油亮光澤。先倒入米酒大火煮至酒精揮發，再依序加入醬油與素蠔油拌勻，轉小火蓋鍋煮約 5 分鐘讓菇肉吸飽醬汁。\n4. **收汁與起鍋**：加入蒜頭、紅辣椒切片與蔥段，最後淋上少許黑麻油及放入一把九層塔快速拌勻即可關火出鍋。\n\n## 💡 廚神小撇步\n\n* **花刀與厚切**：切 2 公分厚度能保留杏鮑菇的多汁口感，劃花刀可大幅縮短吸醬入味的時間。\n* **冷油煸薑**：麻油不耐高溫，一定要冷油搭配橄欖油慢火煸薑，才不會苦澀並能徹底釋放薑香。",
