      "summary": "九層塔燒雞 絕不錯過woodywoody315的任何貼文 註冊 Instagram，隨時掌握最新消息。 🥣 食材清單 主料：雞腿2片、雞胸2片 調味料：是非常配飯的下飯菜、很適合帶便當喔、時間：30分鐘、份數：2人、九層塔1大把、白飯320克、蒜末5克、醬油2大匙、蠔油2大匙、魚露2茶匙 🍳 製作步...",
      "content": "# 九層塔燒雞\n\n絕不錯過woodywoody315的任何貼文 註冊 Instagram，隨時掌握最新消息。\n\n🥣 食材清單\n  * **主料**：雞腿2片、雞胸2片\n  * **調味料**：是非常配飯的下飯菜、很適合帶便當喔、時間：30分鐘、份數：2人、九層塔1大把、白飯320克、蒜末5克、醬油2大匙、蠔油2大匙、魚露2茶匙\n\n🍳 製作步驟\n1. 將食材洗淨切好備用。\n2. 下鍋翻炒並加入調味汁。\n3. 煮至入味熟透後即可起鍋盛盤。\n\n💡 廚神小撇步\n  * 可依個人口味調整調味料用量，控制火候以維持良好口感。",
