    "Recipes/九層塔香腸炒糯米腸.md": {
      "title": "九層塔香腸炒糯米腸",
      "tags": [
        "豬肉料理",
        "米料理",
        "香腸",
        "糯米腸",
        "台灣小吃",
        "下酒菜",
        "家常菜",
        "食譜"
      ],
      "author": "wan_wan0913",
      "source": "https://www.instagram.com/reel/DZMNYTcTEL9/",
      "ingredients": "*   香腸：3 條 (切斜片)\n*   糯米腸：3 條 (切厚片)\n*   洋蔥 (小)：1 顆 (切絲)\n*   九層塔：1 大把\n*   蒜醬：1 大匙 (或蒜末適量)\n*   食用油：少許 (煎米腸用)",
      "summary": "九層塔香腸炒糯米腸 這是一道將經典台灣小吃「大腸包小腸」解構並重新詮釋的熱炒家常菜。將香腸與糯米腸切片後分別煎至兩面金黃焦香，再搭配洋蔥絲、蒜醬以及濃郁的九層塔快速拌炒，不僅香氣逼人，更是絕佳的下飯菜與下酒菜。 食材 香腸：3 條 切斜片 糯米腸：3 條 切厚片 洋蔥 小：1 顆 切絲 九層塔：1 ...",
      "content": "# 九層塔香腸炒糯米腸\n\n這是一道將經典台灣小吃「大腸包小腸」解構並重新詮釋的熱炒家常菜。將香腸與糯米腸切片後分別煎至兩面金黃焦香，再搭配洋蔥絲、蒜醬以及濃郁的九層塔快速拌炒，不僅香氣逼人，更是絕佳的下飯菜與下酒菜。\n\n## 食材\n\n*   香腸：3 條 (切斜片)\n*   糯米腸：3 條 (切厚片)\n*   洋蔥 (小)：1 顆 (切絲)\n*   九層塔：1 大把\n*   蒜醬：1 大匙 (或蒜末適量)\n*   食用油：少許 (煎米腸用)\n\n## 調味料\n\n*   萬用胡椒粉 (或黑胡椒粉)：適量\n*   米酒：1 大匙\n*   醬油：1 大匙\n\n## 步驟\n\n1.  **煎香腸**：香腸切片。平底鍋加熱不放油，直接放入香腸片，以中小火煎至兩面呈現金黃焦香、釋放出多餘的豬油，撈起備用。\n2.  **煎米腸**：糯米腸切成厚片。使用煎香腸逼出的原鍋豬油（若不夠可補少許食用油），放入糯米腸片，煎至兩面表皮呈金黃微脆狀，撈起備用。*（註：先煎過可以使糯米腸外皮定型，避免後續拌炒時碎掉）*\n3.  **爆香配料**：利用鍋中餘油，倒入洋蔥絲與一大匙蒜醬，爆炒至洋蔥熟軟並飄散出濃郁蒜香。\n4.  **下鍋拌炒**：將煎好的香腸片與糯米腸片重新倒回鍋中，與洋蔥絲快速翻炒均勻。\n5.  **調味與起鍋**：沿鍋邊淋入醬油、米酒，並撒上適量胡椒粉增香。最後投入洗淨的九層塔，大火快速攪拌均勻，待九層塔香氣散發且微縮水後即可起鍋裝盤。\n\n## 料理筆記\n\n*   糯米腸切片時不要切得太薄，否則在煎與拌炒的過程中容易糊爛散開。\n*   香腸本身帶有豐富油脂與鹹甜味，因此煎香腸時不需額外加油，調味時醬油量也不宜過多。",
      "md5": "92c7c1986bb2e8148bfc743fc991618d"
    },
