      "source": "https://www.instagram.com/reel/DXRbNWiDaVU/",
      "ingredients": "### 主料\n*   去骨雞腿排：1 公斤 (約 3-4 片)",
      "summary": "乾煎去骨雞腿排 這是一道外皮金黃酥脆、內裡肉質多汁的香煎去骨雞腿排。秘訣在於薄裹玉米澱粉鎖水，並在起鍋前利用淋入料酒蓋燜的方式，讓雞腿肉熟而不柴。 🥣 食材清單 主料 去骨雞腿排：1 公斤 約 34 片 調味料 按 1 公斤比例 鹽巴：5 克 約 0.5% 生抽 醬油：10 克 約 1% 蠔油：10...",
      "content": "# 乾煎去骨雞腿排\n\n這是一道外皮金黃酥脆、內裡肉質多汁的香煎去骨雞腿排。秘訣在於薄裹玉米澱粉鎖水，並在起鍋前利用淋入料酒蓋燜的方式，讓雞腿肉熟而不柴。\n\n## 🥣 食材清單\n\n### 主料\n*   去骨雞腿排：1 公斤 (約 3-4 片)\n\n### 調味料 (按 1 公斤比例)\n*   鹽巴：5 克 (約 0.5%)\n*   生抽 (醬油)：10 克 (約 1%)\n*   蠔油：10 克 (約 1%)\n*   砂糖：5 克 (約 0.5%)\n*   料酒 (米酒)：20 克 (約 2%，抓醃用)\n*   黑胡椒粒：適量\n*   薑末：5 克 (約 0.5%)\n*   玉米澱粉：適量 (裹粉與鎖水用)\n*   起鍋用料酒 (米酒)：少許\n\n## 🍳 製作步驟\n\n1.  **雞腿去骨處理**：去骨雞腿排沿著骨頭邊緣用刀背刮除肌肉，至與軟骨相連處切斷筋膜，將骨頭完全取下。\n2.  **抓醃鎖水**：將去骨後的雞腿肉放入碗中，加入鹽巴、生抽、蠔油、砂糖、薑末、黑胡椒以及 2% 的料酒，用手徹底抓勻，讓肉吃進水分與調味。\n3.  **上粉**：醃好後，撒上一層薄薄的玉米澱粉均勻抓裹在雞腿肉表面。靜置醃製 10 分鐘以上。（可一次製作大量放入冰箱冷藏保存至多3天，吃之前再拍上一層薄粉）。\n4.  **熱鍋定型**：大火將平底鍋燒熱至微微冒煙，轉小火，加入剛好鋪滿鍋底的油。雞皮面朝下放入雞排，煎 2~3 分鐘定型，不要隨意翻動以防破壞表皮脆殼。\n5.  **雙面煎熟**：待雞皮煎出金黃脆殼後翻面。之後每 2-3 分鐘翻面一次，全程煎約 10~12 分鐘（若擔心不熟可煎至 15 分鐘，雞腿肉不易變柴）。\n6.  **淋酒蓋燜**：起鍋前，將少許料酒淋在鍋邊四周（注意不要直接淋在雞皮上以防表皮軟化），迅速蓋上鍋蓋，用餘溫和酒氣燜 1 分鐘，即可出鍋切塊。\n\n## 💡 廚神小撇步\n*   **熱鍋下鍋**：與冷鍋冷油煎不同，由於雞排表面裹有澱粉，必須熱鍋下鍋才能讓表面迅速定型結脆，避免粉面吸收過多油脂。\n*   **最後蓋燜**：最後往鍋邊噴灑料酒並蓋燜，是讓雞胸/雞腿肉內部保持水嫩、多汁且香氣四溢的關鍵技巧。",
