      "author": "未知",
      "source": "https://www.instagram.com/reel/DQlykbVDk_P/?igsh=MTRydWtzaXA3YnUzNQ==",
      "ingredients": "### 主料\n- 糯米椒或肥粗青椒：3 根（選擇直挺、梗粗、含水量適中者）\n- 市售Q彈蝦滑：150 克（若自製：蝦仁 150 克、鹽 1/2 茶匙、太白粉 1 小匙、白胡椒粉少許，朝同方向強力攪拌至起膠上勁）",
      "summary": "剪刀極簡虎皮青椒釀蝦滑 「青椒釀肉/釀蝦滑」是一道老少咸宜的廣式茶樓名菜，但傳統切剖青椒、掏籽、塞餡的做法繁複且極易在煎煮時「皮肉分離」。本食譜解密近期風靡社群的「剪刀極簡版」——用廚房剪刀輕鬆將青椒剪成完整小圓筒，並利用「青椒內壁薄撲太白粉」的澱粉糊化機制，鎖死青椒與蝦滑，確保翻面拍打絕不脫落。蝦...",
      "content": "# 剪刀極簡虎皮青椒釀蝦滑\n\n「青椒釀肉/釀蝦滑」是一道老少咸宜的廣式茶樓名菜，但傳統切剖青椒、掏籽、塞餡的做法繁複且極易在煎煮時「皮肉分離」。本食譜解密近期風靡社群的「剪刀極簡版」——用廚房剪刀輕鬆將青椒剪成完整小圓筒，並利用**「青椒內壁薄撲太白粉」**的澱粉糊化機制，鎖死青椒與蝦滑，確保翻面拍打絕不脫落。蝦滑脆彈、青椒帶有誘人虎皮焦香，包裹著濃稠鮮美的照燒醬汁，好看又極度下飯！\n\n## 🥣 食材清單\n\n### 主料\n- 糯米椒或肥粗青椒：3 根（選擇直挺、梗粗、含水量適中者）\n- 市售Q彈蝦滑：150 克（若自製：蝦仁 150 克、鹽 1/2 茶匙、太白粉 1 小匙、白胡椒粉少許，朝同方向強力攪拌至起膠上勁）\n\n### 🧼 黏合劑與煎油\n- 太白粉（或玉米澱粉）：1 大匙（抹青椒內壁用）\n- 食用油：1.5 大匙\n\n### 🍯 萬能照燒燜煮醬汁\n- 醬油（生抽）：1.5 大匙\n- 老抽（草菇老抽）：1/2 小匙（著色用，無可省略）\n- 蠔油：1 大匙\n- 白糖：1/2 茶匙\n- 清水：3 大匙\n\n---\n\n## 🍳 製作步驟\n\n1. **剪刀流處理青椒（省時省力完整圓筒步）**：\n   - 青椒洗淨擦乾。用廚房剪刀在青椒頂部**繞蒂頭剪一圈**，直接將蒂頭連同內部的辣椒籽與白色辣筋整顆乾淨拉出。\n   - 用剪刀直接將空心的青椒橫向**剪成約 2.5 - 3 公分寬的完整小圓筒段**。\n   > [!TIP]\n   > **圓筒包裹物理優勢**：相較於將青椒對半剖開，完整的圓筒青椒在受熱時能 360 度鎖定內部的蝦滑，提供極佳的空間束縛，使蝦滑在受熱緊縮時不會輕易邊緣外翻或脫落。\n2. **內壁薄撲乾粉（防滑脫核心步）**：\n   將剪好的青椒段放入盤中，撒入 1 大匙太白粉。用筷子或手晃動青椒，**確保每個青椒圓筒的「內壁表面」都均勻裹上一層薄薄的乾太白粉**，隨後拍掉多餘的粉。\n   > [!IMPORTANT]\n   > **防止皮肉分離的化學機制**：青椒內壁光滑且在加熱時會釋放水分，如果直接釀入蝦滑，煎煮時滲出的水汽會形成滑動水膜，導致蝦滑滑脫。在內壁薄撲乾太白粉，澱粉在接觸水汽與煎鍋熱量時會迅速產生**「澱粉糊化（Gelatinization）」**，形成粘性極強的澱粉膠，將蝦滑與青椒緊緊「焊」在一起。\n3. **釀入蝦滑**：\n   用小勺子或抹刀，將蝦滑塞滿青椒圓筒。**用勺子背部將兩端抹平、壓實**，使其與青椒切面齊平。\n4. **蝦肉面朝下慢煎**：\n   平底鍋倒入 1.5 大匙油，大火燒熱後轉小火。**將青椒段「蝦肉露出面朝下」平放入鍋**。小火慢煎約 3 分鐘，煎至蝦滑定型並呈現焦黃色。\n5. **翻面煎出虎皮青椒（美拉德焦香）**：\n   用筷子將青椒圓筒翻面（青椒皮朝下）。此時可以稍微將青椒圓筒**側躺煎其外皮**。調中火，利用鍋底油脂將青椒外皮煎至表皮起皺並出現微焦的黑斑（即虎皮效果）。\n6. **醬汁燜煮與自乳化**：\n   將生抽 1.5 大匙、老抽 1/2 小匙、蠔油 1 大匙、白糖 1/2 茶匙與清水 3 大匙在碗中調勻，直接淋入鍋中。蓋上鍋蓋，**中小火燜煮 2 分鐘**確保蝦滑深處熟透。\n7. **大火收汁掛味**：\n   打開鍋蓋，轉大火收汁，期間不斷晃動平底鍋，讓釋放出的蝦油、醬汁與青椒表面的太白粉微粒在高溫下自然交融，收乾至醬汁紅亮且均勻掛在青椒段表面，即可出鍋裝盤！",
