      "author": "未知",
      "source": "https://www.instagram.com/reel/DbsvwwiJcZ3/",
      "ingredients": "### 主料\n* 五香豆乾 2 斤（約 1.2 kg）\n* 蒜頭 6-8 顆（切片或拍碎）\n* 辣椒 1 根（切片）\n* 八角 2 顆",
      "summary": "古早味滷豆乾 冷吃熱食都無敵美味的古早味滷豆乾！將五香豆乾先經過川燙，再放入特調鹹甘醬汁中不斷翻炒收汁。隨著水份慢慢收乾，豆乾會越滷越軟 Q 彈牙，是絕佳的下酒菜與家庭常備小菜。 🥣 食材清單 主料 五香豆乾 2 斤（約 1.2 kg） 蒜頭 68 顆（切片或拍碎） 辣椒 1 根（切片） 八角 2 ...",
      "content": "# 古早味滷豆乾\n\n冷吃熱食都無敵美味的古早味滷豆乾！將五香豆乾先經過川燙，再放入特調鹹甘醬汁中不斷翻炒收汁。隨著水份慢慢收乾，豆乾會越滷越軟 Q 彈牙，是絕佳的下酒菜與家庭常備小菜。\n\n## 🥣 食材清單\n\n### 主料\n* 五香豆乾 2 斤（約 1.2 kg）\n* 蒜頭 6-8 顆（切片或拍碎）\n* 辣椒 1 根（切片）\n* 八角 2 顆\n\n### 調味料醬汁（比例參考）\n* 食用油（或橄欖油） 一般飯碗 6 分滿\n* 醬油 一般飯碗 8 分滿\n* 二砂（黃糖） 一般飯碗 8 分滿\n\n## 🍳 製作步驟\n\n1. **川燙豆乾**：煮一鍋沸水，將五香豆乾放入川燙約 2-3 分鐘去除豆騷味，撈出瀝乾備用。\n2. **炒香醬汁**：起鍋倒入食用油、醬油、二砂、八角、蒜頭與辣椒，開中火慢煮並持續拌炒，直至糖融化且醬汁呈現煮沸起泡狀態。\n3. **下豆乾翻炒**：將川燙瀝乾的豆乾倒入鍋中與醬汁均勻混合。\n4. **收汁至所需 Q 度**：轉中小火持續翻炒豆乾（滷越久豆乾水分會越收濃縮，口感越 Q 彈），炒至醬汁濃稠完全吸附在豆乾表面且達到喜愛的 Q 軟程度即可盛起。\n\n## 💡 廚神小撇步\n\n* **江湖一點訣**：滷豆乾關鍵在於「油、醬油、糖」的經典比例與持續翻炒收汁，水份慢慢蒸發後，醬汁會濃縮裹在豆乾表面形成彈牙外皮。\n* **冷凍豆乾提問處置**：若使用冷凍過有氣孔的豆乾，可延長慢火浸滷時間，讓氣孔充份吸飽醬汁精華。",
