      "content": "# 台式紅燒魚\n\n絕不錯過yukaihsu的任何貼文 註冊 Instagram，隨時掌握最新消息。\n\n🥣 食材清單\n  * **主料**：1 個讚、回覆、hower85_03_11、2週、我愛腰哥，腰哥愛我、2個讚、回覆、wade1632102、2週、再加點洋蔥👍\n  * **調味料**：鹽、醬油、食用油適量。\n\n🍳 製作步驟\n1. 👉 記得先收藏起來\n2. 你們家的紅燒魚會加烏醋嗎？🤔\n3. #紅燒魚\n4. #魚料理\n5. #烏醋\n6. #家庭料理\n7. #晚餐\n8. weichih0927\n9. 週\n10. 這尾金目鯛應該要個2000台幣\n11. 個讚\n12. 回覆\n\n💡 廚神小撇步\n  * 可依個人口味調整調味料用量，控制火候以維持良好口感。",
