      "source": "https://www.instagram.com/reel/DRrgqVCj3jX/?igsh=MXFvNXdjdzV4aTlleg==",
      "ingredients": "### 主料\n* 去骨雞腿肉：800 克\n* 蒜泥：15 克\n* 薑泥：15 克\n* 太白粉：80 克",
      "summary": "多汁唐揚炸雞 這是一道餐廳秘方的日式唐揚炸雞。利用美乃滋包覆醃料，能牢牢鎖住雞肉的水分，讓炸出來的雞塊外酥內嫩、咬下去多汁無比，是家裡餐桌上絕對秒殺的美味。 🥣 食材清單 主料 去骨雞腿肉：800 克 蒜泥：15 克 薑泥：15 克 太白粉：80 克 調味料 醬油：1 大匙 水：50 毫升 味醂：1...",
      "content": "# 多汁唐揚炸雞\n\n這是一道餐廳秘方的日式唐揚炸雞。利用美乃滋包覆醃料，能牢牢鎖住雞肉的水分，讓炸出來的雞塊外酥內嫩、咬下去多汁無比，是家裡餐桌上絕對秒殺的美味。\n\n## 🥣 食材清單\n\n### 主料\n* 去骨雞腿肉：800 克\n* 蒜泥：15 克\n* 薑泥：15 克\n* 太白粉：80 克\n\n### 調味料\n* 醬油：1 大匙\n* 水：50 毫升\n* 味醂：1 大匙\n* 米酒：1 大匙\n* 日式美乃滋：100 克\n* 鹽：0.5 茶匙\n\n## 🍳 製作步驟\n\n1. **食材處理**：將去骨雞腿肉洗淨，用廚房紙巾擦乾，切成一口大小的塊狀。\n2. **調味抓醃**：雞腿肉加入蒜泥、薑泥、鹽、醬油、味醂與水混合，用手輕輕抓拌按摩，直到水分被雞肉充分吸收。\n3. **美乃滋醃漬**：加入日式美乃滋拌勻，讓美乃滋均勻包覆醃料，蓋上保鮮膜醃漬 30 分鐘入味。\n4. **裹粉準備**：醃漬完成後，加入太白粉拌勻，使雞肉表面均勻裹上一層薄粉。\n5. **初次油炸**：起油鍋，將油溫加熱至約 170℃（可用木筷測試，周圍起小泡泡）。轉中小火，將雞肉塊一塊一塊放入油鍋中，待 30 秒定型後再翻動。炸約 3 分鐘至熟後撈起瀝油。\n6. **二次回炸**：將火轉大，讓油溫再次升高，放入雞塊回炸約 20 秒，炸至外表金黃酥脆即可撈出，瀝乾盛盤。\n\n## 💡 廚神小撇步\n\n* **多汁秘訣**：醃肉時一定要抓拌至水分被雞肉完全吸收；美乃滋富含油脂，能有效鎖住肉汁並軟化肉質，是雞肉軟嫩多汁的關鍵。若想降低熱量，可以嘗試使用無糖優格代替部分美乃滋。\n* **回炸逼油**：第一次炸是為了熟透，第二次高油溫短時間回炸可以逼出多餘油分，並使外皮更加酥脆。",
