      "source": "https://www.instagram.com/reel/Da4TpYahnbd/",
      "ingredients": "* **主料**：板豆腐 1 盒、蘑菇 8 朵、洋蔥 1/4 顆、蔥花適量。\n  * **調味料**：奶油 1 塊（約 15g）、醬油 1.5 大匙、蠔油 1 大匙、砂糖 1 茶匙、清水 3 大匙。",
      "summary": "奶油蘑菇鐵板豆腐 金黃焦香的板豆腐吸收了乾煎蘑菇的鮮香與奶油洋蔥的濃郁醬汁，口感層次豐富，香氣逼人。 🥣 食材清單 主料：板豆腐 1 盒、蘑菇 8 朵、洋蔥 1/4 顆、蔥花適量。 調味料：奶油 1 塊（約 15g）、醬油 1.5 大匙、蠔油 1 大匙、砂糖 1 茶匙、清水 3 大匙。 🍳 製作步驟...",
      "content": "# 奶油蘑菇鐵板豆腐\n\n金黃焦香的板豆腐吸收了乾煎蘑菇的鮮香與奶油洋蔥的濃郁醬汁，口感層次豐富，香氣逼人。\n\n🥣 食材清單\n  * **主料**：板豆腐 1 盒、蘑菇 8 朵、洋蔥 1/4 顆、蔥花適量。\n  * **調味料**：奶油 1 塊（約 15g）、醬油 1.5 大匙、蠔油 1 大匙、砂糖 1 茶匙、清水 3 大匙。\n\n🍳 製作步驟\n1. 板豆腐切厚片，入鍋煎至雙面呈金黃色後先起鍋備用。\n2. 蘑菇切片，不放油下鍋乾煎至出水並炒乾水分爆香。\n3. 加入洋蔥絲與奶油一塊，均勻翻炒至洋蔥軟化散發奶香。\n4. 將煎好的豆腐放回鍋中，倒入調好的醬汁（醬油、蠔油、糖、水）。\n5. 蓋鍋悶煮約 2 分鐘讓豆腐充分汲取湯汁，開蓋撒上蔥花快速拌炒均勻即可。\n\n💡 廚神小撇步\n  * 蘑菇先乾煎炒乾水分能徹底釋放真菌鮮味。\n  * 板豆腐煎至雙面金黃形成抗煮表皮，更能鎖住內裡豆香與吸附醬汁。",
