      "ingredients": "* **主料**：✅五花肉片200g、✅皮蛋4顆、✅蒜苗80g、✅大辣椒1條、✅蒜頭20g、✅金鈎蝦10g、✅油1大匙、✅白胡椒粉1/3小匙、✅黑豆醬油1大匙、✅黑豆醬油膏1大匙\n  * **調味料**：----------------------------------、有任何想學的料理也歡迎在底下告訴阿慶師唷~、阿慶師Facebook粉絲團👉https://www.facebook.com/achingchef、阿慶師IG👉https://www.instagram.com/achingchef/、📍料理小教室📍、1大匙=15ml=15cc、1小匙=5ml=5cc、1飯碗=200cc、1米杯=150cc、-",
      "summary": "我推薦給你的晚餐皮蛋煎過更香肉片小炒超夠味阿慶師 絕不錯過achingchef的任何貼文 註冊 Instagram，隨時掌握最新消息。 🥣 食材清單 主料：✅五花肉片200g、✅皮蛋4顆、✅蒜苗80g、✅大辣椒1條、✅蒜頭20g、✅金鈎蝦10g、✅油1大匙、✅白胡椒粉1/3小匙、✅黑豆醬油1大匙、✅...",
      "content": "# 我推薦給你的晚餐皮蛋煎過更香肉片小炒超夠味阿慶師\n\n絕不錯過achingchef的任何貼文 註冊 Instagram，隨時掌握最新消息。\n\n🥣 食材清單\n  * **主料**：✅五花肉片200g、✅皮蛋4顆、✅蒜苗80g、✅大辣椒1條、✅蒜頭20g、✅金鈎蝦10g、✅油1大匙、✅白胡椒粉1/3小匙、✅黑豆醬油1大匙、✅黑豆醬油膏1大匙\n  * **調味料**：----------------------------------、有任何想學的料理也歡迎在底下告訴阿慶師唷~、阿慶師Facebook粉絲團👉https://www.facebook.com/achingchef、阿慶師IG👉https://www.instagram.com/achingchef/、📍料理小教室📍、1大匙=15ml=15cc、1小匙=5ml=5cc、1飯碗=200cc、1米杯=150cc、-\n\n🍳 製作步驟\n1. 將食材洗淨切好備用。\n2. 下鍋翻炒並加入調味汁。\n3. 煮至入味熟透後即可起鍋盛盤。\n\n💡 廚神小撇步\n  * 可依個人口味調整調味料用量，控制火候以維持良好口感。",
