      "source": "https://www.instagram.com/reel/DQS7xfPAUIm/?igsh=ZHE2bTJ5MDFzdDJs",
      "ingredients": "*   雞蛋：3 顆 (蛋液約 150 ml)\n*   日式高湯包：1 包 (如昆布柴魚高湯包)\n*   水：400 ml (用於煮高湯包，最終取 300 ml 使用)",
      "summary": "日式滑嫩蒸蛋 日本蒸蛋平滑無氣孔、香氣濃郁的關鍵在於不用清水打蛋，而是使用「有味道的高湯水」，並且維持雞蛋液與高湯水 1:2 的完美黃金比例。 食材 雞蛋：3 顆 蛋液約 150 ml 日式高湯包：1 包 如昆布柴魚高湯包 水：400 ml 用於煮高湯包，最終取 300 ml 使用 黃金比例 雞蛋液...",
      "content": "# 日式滑嫩蒸蛋\n\n日本蒸蛋平滑無氣孔、香氣濃郁的關鍵在於不用清水打蛋，而是使用「有味道的高湯水」，並且維持雞蛋液與高湯水 1:2 的完美黃金比例。\n\n## 食材\n\n*   雞蛋：3 顆 (蛋液約 150 ml)\n*   日式高湯包：1 包 (如昆布柴魚高湯包)\n*   水：400 ml (用於煮高湯包，最終取 300 ml 使用)\n\n## 黃金比例\n\n*   **雞蛋液 : 高湯水 = 1 : 2** (3 顆蛋約 150 ml 配上放涼的高湯水 300 ml)\n\n## 步驟\n\n1.  **煮日式高湯**：鍋中倒入 400 ml 水，放入日式高湯包煮滾 3 分鐘，充分煮出高湯風味後，將高湯包取出。**高湯必須完全放涼**後才能使用，避免高溫將蛋液燙熟結塊。\n2.  **打散蛋液**：將 3 顆雞蛋打入碗中，用筷子以貼近碗底的方式輕輕攪散，避免打入過多空氣產生泡泡。\n3.  **混合攪拌**：量取放涼的高湯 300 ml，徐徐倒入打散的蛋液中，輕輕攪拌均勻。\n4.  **過篩去氣泡**：將混合好的高湯蛋液用細網篩過篩 1~2 次，濾掉未打散的蛋白、蛋筋與氣泡，這是蒸蛋表面平滑如布丁的關鍵步驟。\n5.  **蒸煮**：將過篩後的蛋液倒入耐熱容器（如茶碗蒸杯或深瓷盤），用廚房紙巾輕輕吸掉表面殘留的微小氣泡。\n    *   *蒸鍋法*：水滾後放入蒸鍋，蓋上鍋蓋（**鍋蓋邊緣需插一根筷子留下一道小縫**，避免鍋內溫度過高導致蛋液膨脹產生孔洞），以中小火蒸約 12~15 分鐘。\n    *   *電鍋法*：外鍋放 1 杯水，放上蒸架與蛋液，電鍋蓋一樣**夾一根筷子留縫**，蒸至開關跳起即可。\n\n## 料理筆記\n\n*   日式高湯包本身通常已含有淡淡的鹹味，因此不需要額外加鹽。如果買到的高湯包完全無調味，可以在混合蛋液時加入極少量的鹽或薄鹽醬油調味。\n*   此高湯底除了蒸蛋，也適合煮味噌湯、燙青菜、火鍋湯底或烏龍麵，十分萬用。",
