      "author": "未知",
      "source": "https://www.instagram.com/reel/DShlR-EDyNW/?igsh=ZGV4NGU1cWJteWdu",
      "ingredients": "### 主料\n- 板豆腐（或嫩豆腐）：400 克（切小方丁）\n- 鴻喜菇：80 克（切除根部，掰成小朵）\n- 青蔥：1 根（切細蔥花，約 10 克）",
      "summary": "日式滑嫩豆腐味噌湯 在日式定食中，一碗香氣四溢、豆香醇厚的味噌湯是溫暖身心的靈魂。許多人在家煮味噌湯常覺得「死鹹」或帶有「酸苦味」，關鍵在於火候控制。正宗日式料亭做法講究「味噌不能大火煮沸」，因為高溫會破壞發酵味噌的精緻香氣與活菌。本食譜分享如何以「低溫融化法」，在家煮出味道乾淨、醇香細緻的經典日式...",
      "content": "# 日式滑嫩豆腐味噌湯\n\n在日式定食中，一碗香氣四溢、豆香醇厚的味噌湯是溫暖身心的靈魂。許多人在家煮味噌湯常覺得「死鹹」或帶有「酸苦味」，關鍵在於火候控制。正宗日式料亭做法講究「味噌不能大火煮沸」，因為高溫會破壞發酵味噌的精緻香氣與活菌。本食譜分享如何以「低溫融化法」，在家煮出味道乾淨、醇香細緻的經典日式味噌湯。\n\n## 🥣 食材清單\n\n### 主料\n- 板豆腐（或嫩豆腐）：400 克（切小方丁）\n- 鴻喜菇：80 克（切除根部，掰成小朵）\n- 青蔥：1 根（切細蔥花，約 10 克）\n\n### 🥣 湯底與調味\n- 清水：800 毫升\n- 柴魚醬油（昆布醬油）：1 大匙\n- 味噌（黃味噌或赤白味噌混和）：80 克（**黃金湯水比例為 1 : 10**，即 100 毫升水配 10 克味噌）\n\n---\n\n## 🍳 製作步驟\n\n1. **煮滾高湯底**：\n   在雪平鍋中倒入清水 800 毫升，以大火煮滾。\n2. **煮熟配料**：\n   放入切丁的板豆腐、鴻喜菇朵，並加入柴魚醬油 1 大匙拌勻，大火煮沸後轉中火，煮約 2 - 3 分鐘至鴻喜菇熟透。\n3. **過篩融化味噌（香氣核心）**：\n   將爐火**轉為最小火（或直接關火）**。將味噌 80 克放入細篩網中，將篩網局部浸入湯汁裡，用湯匙背面在網中輕輕畫圈磨化，將味噌慢慢濾入湯鍋中直至完全融化。\n   > [!IMPORTANT]\n   > **味噌不滾的物理學**：味噌是富含活菌與揮發性酯類香氣的發酵食品。如果將味噌放入湯中大火煮沸（100°C 滾煮），高溫會使味噌的香氣分子迅速汽化揮發，且大豆蛋白質會產生微小凝集，導致湯汁變酸、甚至帶有苦澀感。最完美的融入溫度是 **85°C 左右**。\n4. **微溫出鍋**：\n   味噌完全融入後，若剛剛是關火，可開微火再次加溫至「**鍋邊起微小氣泡（即將沸騰但未沸騰狀態）**」。\n5. **撒蔥起鍋**：\n   立刻撒入綠蔥花，隨即關火出鍋盛碗，趁熱享用！\n\n---\n\n## 💡 廚神小撇步\n- **柴魚醬油的妙用**：\n  日式味噌湯的底蘊來自「柴魚昆布高湯（Dashi）」。本食譜使用「柴魚醬油」代替繁瑣的現熬高湯步驟，能快速為清水湯底注入柴魚乾的煙燻鹹鮮感。\n- **鴻喜菇的爆香進階版**：\n  若想讓湯頭多一層油脂香氣，可先在雪平鍋中加極少量的香油，將鴻喜菇倒入小火炒出焦香，再倒入清水煮滾。這樣煮出來的味噌湯會多一層堅果與蕈菇的焦香味。\n- **味噌的保存**：\n  味噌開封後必須放冰箱冷藏，且表面要用保鮮膜緊貼封好，防止接觸空氣氧化變黑、味道變酸。",
