      "source": "https://www.instagram.com/reel/DaVAlY0h1CG/",
      "ingredients": "### 主料\n* 雞腿排：1 片\n* 黑胡椒：少許（醃製用）\n* 白芝麻：少許（最後裝飾用）",
      "summary": "日式照燒雞腿排 這是一款經典的日式家庭料理。照燒（Teriyaki）的靈魂在於砂糖與醬油燉煮出的微甜濃稠醬汁。透過不放油、乾煎雞腿排逼出油脂的技巧，能讓雞皮達到金黃酥脆的完美口感，是一道大朋友小朋友都非常喜愛的家常便當菜。 🥣 食材清單 主料 雞腿排：1 片 黑胡椒：少許（醃製用） 白芝麻：少許（最...",
      "content": "# 日式照燒雞腿排\n\n這是一款經典的日式家庭料理。照燒（Teriyaki）的靈魂在於砂糖與醬油燉煮出的微甜濃稠醬汁。透過不放油、乾煎雞腿排逼出油脂的技巧，能讓雞皮達到金黃酥脆的完美口感，是一道大朋友小朋友都非常喜愛的家常便當菜。\n\n## 🥣 食材清單\n\n### 主料\n* 雞腿排：1 片\n* 黑胡椒：少許（醃製用）\n* 白芝麻：少許（最後裝飾用）\n\n### 照燒醬汁\n* 砂糖：1 匙\n* 醬油：2 匙\n* 蠔油：1 匙\n* 熱開水：300 ml（用來融化砂糖）\n\n## 🍳 製作步驟\n\n1. **去濕備料**：用廚房紙巾徹底擦乾雞腿排表面的水分。這個步驟非常重要，去除多餘水分能確保雞皮煎起來達到酥脆的口感。\n2. **斷筋入味**：在雞腿排的肉面上輕劃 4 刀（可防止肉受熱收縮變形），撒上黑胡椒粉並輕輕拍打，使黑胡椒均勻分佈入味。\n3. **調製醬汁**：在碗中放入 1 匙砂糖、2 匙醬油和 1 匙蠔油，倒入 300 ml 熱開水，攪拌均勻直至砂糖完全融化。\n4. **乾煎雙面**：鍋中不用放油，將雞腿排以「皮朝下」的方式放入鍋中，全程使用中小火。煎約 5～6 分鐘，直到雞皮呈現金黃色且焦脆，即可翻面，將另一面也煎同樣長的時間。\n5. **入醬收汁**：將調好的照燒醬汁倒入鍋中，翻動雞腿排使其兩面都均勻沾裹上醬汁。繼續用中小火燉煮，直到醬汁稍微收乾，呈現微稠狀即可起鍋（切記不要將醬汁完全收乾，要留一些湯汁）。\n6. **切塊淋汁**：將煎好的照燒雞腿排取出切成條狀，盛入盤中，將鍋中剩餘的濃稠照燒醬汁淋在表面，最後撒上白芝麻裝飾即成。\n\n## 💡 廚神小撇步\n* 雞腿排皮朝下煎時，皮煎得夠不夠脆，取決於起初有無徹底將雞皮表面的水份吸乾。\n* 醬汁中加入熱水有助於砂糖迅速溶解，調出來的比例更均勻。\n* 燉煮收汁時不要完全收乾，微微濃稠的照燒醬汁不論是配白飯或是拌麵都是絕佳的白飯殺手。",
