      "ingredients": "### 主料\n*   **白蘿蔔**：1200 克 (約一大根)",
      "summary": "🥕🥢 日式燒蘿蔔 軟爛入味秘訣 「蘿蔔賽人參！」這是一道零失敗的日式燒蘿蔔，口感極為軟爛、多汁且入味。利用「十字刀刻紋」與「燜泡法」，不僅能加快蘿蔔入味的速度，還能完整保持蘿蔔的形狀不軟爛分解。這也是日式關東煮與居酒屋中非常經典的銷魂小菜。 🥣 食材清單 主料 白蘿蔔：1200 克 約一大根 醬汁調...",
      "content": "# 🥕🥢 日式燒蘿蔔 (軟爛入味秘訣)\n\n「蘿蔔賽人參！」這是一道零失敗的日式燒蘿蔔，口感極為軟爛、多汁且入味。利用「十字刀刻紋」與「燜泡法」，不僅能加快蘿蔔入味的速度，還能完整保持蘿蔔的形狀不軟爛分解。這也是日式關東煮與居酒屋中非常經典的銷魂小菜。\n\n## 🥣 食材清單\n\n### 主料\n*   **白蘿蔔**：1200 克 (約一大根)\n\n### 醬汁調味\n*   **柴魚高湯**：500 毫升\n*   **日式醬油**：4 大匙\n*   **味醂**：4 大匙\n*   **水**：500 毫升\n\n---\n\n## 🍳 製作步驟\n\n1.  **處理白蘿蔔 (去纖維與切花)**：\n    *   將白蘿蔔削皮。*(注意：請削去稍厚的外皮，徹底切除皮下的粗纖維，這是蘿蔔口感細緻無渣的關鍵)*。\n    *   將蘿蔔切成約 **2-3 公分** 厚度的圓厚片。\n    *   在每個蘿蔔厚片的其中一面，用刀劃上**十字刀**（深度約蘿蔔厚度的 **1/3** 即可）。這能讓蘿蔔在短時間內快速入味，且燉煮時蘿蔔塊不會散開。\n2.  **鋪鍋與下料**：\n    *   將切好的白蘿蔔塊平鋪在鍋底（十字刀面朝上）。\n    *   倒入日式醬油 4 大匙、味醂 4 大匙、柴魚高湯 500ml 以及清水 500ml。液體量應剛好或接近沒過蘿蔔。\n3.  **煮滾與慢燉**：\n    *   蓋上鍋蓋，開大火煮滾。\n    *   煮滾後轉中小火，繼續保持微滾狀態煮約 **3 分鐘**。\n4.  **燜泡法入味 (核心步驟)**：\n    *   煮滿 3 分鐘後，**關火且絕對不要打開鍋蓋**。\n    *   利用鍋內的餘溫與蒸氣，將蘿蔔在鍋中**燜泡約 20 分鐘**。這能讓柴魚醬汁的甘甜精華慢慢滲透進蘿蔔中心。\n5.  **盛盤**：\n    *   燜泡完成後，蘿蔔應已呈現半透明且用筷子可輕易戳透的軟爛狀態。\n    *   將蘿蔔盛盤，淋上少許鍋中的柴魚醬汁，即可熱騰騰地上桌享用。\n\n---\n\n## 💡 廚神小撇步\n*   **皮削厚一點**：白蘿蔔外皮下方有一層較硬的纖維環，去皮時多削掉 1-2 公釐，燒出來的蘿蔔才會像水梨一樣細緻軟嫩。\n*   **關火燜泡的魔力**：蘿蔔在降溫的過程中，吸收湯汁的能力最強。使用「燜泡法」代替持續大火燉煮，不僅省瓦斯，還能使蘿蔔維持漂亮完整的形狀，不會因為劇烈滾水撞擊而碎裂。",
