      "ingredients": "### 主料\n*   雞腿肉 (或整隻雞切塊)：適量\n*   紅蘿蔔：適量 (切滾刀塊)\n*   香菇：數朵 (洗淨，可對半切)",
      "summary": "日式紅燒雞肉 這是一道帶有柔和甜味與醬油鹹香的日式紅燒雞肉。特點在於利用「麥芽糖」上色與增甜，燉煮出來的雞肉包裹著一層琥珀色油亮醬汁，配上紅蘿蔔與香菇，非常下飯。 🥣 食材清單 主料 雞腿肉 或整隻雞切塊：適量 紅蘿蔔：適量 切滾刀塊 香菇：數朵 洗淨，可對半切 調味料 麥芽糖：適量 可用冰糖/砂糖...",
      "content": "# 日式紅燒雞肉\n\n這是一道帶有柔和甜味與醬油鹹香的日式紅燒雞肉。特點在於利用「麥芽糖」上色與增甜，燉煮出來的雞肉包裹著一層琥珀色油亮醬汁，配上紅蘿蔔與香菇，非常下飯。\n\n## 🥣 食材清單\n\n### 主料\n*   雞腿肉 (或整隻雞切塊)：適量\n*   紅蘿蔔：適量 (切滾刀塊)\n*   香菇：數朵 (洗淨，可對半切)\n\n### 調味料\n*   麥芽糖：適量 (可用冰糖/砂糖代替，但麥芽糖風味與光澤更佳)\n*   醬油：適量\n*   米酒：適量\n*   水：適量\n\n## 🍳 製作步驟\n\n1.  **煎香雞肉**：熱鍋，將雞肉皮朝下放入鍋中（可不加或加少許油），煎至兩面呈金黃上色。\n2.  **加入配料**：放入切好的紅蘿蔔塊與香菇，與雞肉一同翻炒，使其沾裹上雞油香氣。\n3.  **上糖與燉煮**：加入適量醬油、米酒、水，並下入適量麥芽糖。\n    *   *麥芽糖處理技巧*：拿取麥芽糖時，手可先沾少許冰水防黏，即可輕鬆拿取而不黏手。\n4.  **小火慢燉**：蓋上鍋蓋，轉小火慢慢燉煮約 30 分鐘，使紅蘿蔔變軟、雞肉完全入味。\n5.  **收汁裝盤**：燉煮至醬汁收濃、呈現黏稠金黃色並均勻包裹住雞肉與食材後，即可起鍋裝盤。\n\n## 💡 廚神小撇步\n*   **不黏手技巧**：挖取麥芽糖時，先將手部或餐具沾點冰水，麥芽糖便不會黏在手或餐具上，操作十分便利。\n*   **紅蘿蔔要先下**：紅蘿蔔需要足夠的時間燉煮才能軟爛透心，因此要與香菇一同在初期下鍋慢火燜燉。",
