      "summary": "日式起司煎馬鈴薯 這道在日本非常熱門的馬鈴薯料理，將軟糯的馬鈴薯裹上滿滿的焦香起司，外酥內軟，鹹香四溢，是大人小孩都會一口接一口停不下來的美味點心。 🥣 食材清單 主料 馬鈴薯：2 顆 起司絲（披薩乳酪絲）：3 大把 調味料 蠔油：1 大匙 大蒜鹽：少許 食用油：適量 🍳 製作步驟 1. 準備馬鈴薯...",
      "content": "# 日式起司煎馬鈴薯\n\n這道在日本非常熱門的馬鈴薯料理，將軟糯的馬鈴薯裹上滿滿的焦香起司，外酥內軟，鹹香四溢，是大人小孩都會一口接一口停不下來的美味點心。\n\n## 🥣 食材清單\n\n### 主料\n* 馬鈴薯：2 顆\n* 起司絲（披薩乳酪絲）：3 大把\n\n### 調味料\n* 蠔油：1 大匙\n* 大蒜鹽：少許\n* 食用油：適量\n\n## 🍳 製作步驟\n\n1. **準備馬鈴薯**：將馬鈴薯洗淨切塊（帶皮或去皮皆可），放入水中浸泡一下去除多餘澱粉。\n2. **微波預熟**：將瀝乾的馬鈴薯放入微波專用容器中，加蓋微波 3 分鐘，翻面後再微波 2 分鐘，至馬鈴薯變軟。\n3. **下鍋煸炒**：平底鍋倒入適量食用油，放入馬鈴薯翻炒至表面微焦（帶點焦香色）。\n4. **調味**：淋上蠔油與大蒜鹽，翻炒均勻，讓馬鈴薯均勻裹上醬汁。\n5. **加入起司**：用廚房紙巾吸除鍋中多餘油分。撒入三大把起司絲，鋪滿馬鈴薯表面。\n6. **煎至定型**：起司受熱融化並開始與馬鈴薯融合，翻面或煎至底部起司呈金黃焦香的起司脆片狀，即可出鍋盛盤。\n\n## 💡 廚神小撇步\n\n* 馬鈴薯切塊後浸泡水可以洗去表面澱粉，煎的時候比較不容易黏鍋。\n* 先微波可以大幅縮短在平底鍋裡煎熟的時間，確保內部口感鬆軟。\n* 起司融化後不要急著翻動，等底部煎到微微焦黃呈脆片狀時最香最好吃。",
