      "ingredients": "- **主料**：\n  - 牛小排火鍋肉片（或豬肉片）200～250g\n  - 馬鈴薯 1-2顆（滾刀切塊）\n  - 洋蔥 ½顆（切絲）\n  - 紅蘿蔔 ½條（滾刀切塊，可省略）\n  - 蒟蒻絲 / 板蒟蒻 適量（可省略）\n  - 蔥花 / 蒜末 少許\n- **靈魂高湯調味**：\n  - 水 500ml\n  - 醬油 3.5大匙\n  - 味醂 2大匙\n  - 米酒（或清酒）1大匙\n  - 砂糖 2大匙\n  - 烹大師（或柴魚高湯粉）1大匙\n  - 七味粉 少許（依喜好添加）",
      "summary": "日式馬鈴薯燉肉 日本家庭最具代表性的溫馨家常菜！肉香、蔬菜甜味與柴魚高湯甘甜交融，馬鈴薯鬆軟入味，一鍋搞定蛋白質與蔬菜！ 🥣 食材清單 主料： 牛小排火鍋肉片（或豬肉片）200～250g 馬鈴薯 12顆（滾刀切塊） 洋蔥 ½顆（切絲） 紅蘿蔔 ½條（滾刀切塊，可省略） 蒟蒻絲 / 板蒟蒻 適量（可省...",
      "content": "# 日式馬鈴薯燉肉\n\n日本家庭最具代表性的溫馨家常菜！肉香、蔬菜甜味與柴魚高湯甘甜交融，馬鈴薯鬆軟入味，一鍋搞定蛋白質與蔬菜！\n\n🥣 食材清單\n- **主料**：\n  - 牛小排火鍋肉片（或豬肉片）200～250g\n  - 馬鈴薯 1-2顆（滾刀切塊）\n  - 洋蔥 ½顆（切絲）\n  - 紅蘿蔔 ½條（滾刀切塊，可省略）\n  - 蒟蒻絲 / 板蒟蒻 適量（可省略）\n  - 蔥花 / 蒜末 少許\n- **靈魂高湯調味**：\n  - 水 500ml\n  - 醬油 3.5大匙\n  - 味醂 2大匙\n  - 米酒（或清酒）1大匙\n  - 砂糖 2大匙\n  - 烹大師（或柴魚高湯粉）1大匙\n  - 七味粉 少許（依喜好添加）\n\n🍳 製作步驟\n1. 備料：馬鈴薯與紅蘿蔔切滾刀塊，洋蔥切絲。\n2. 炒香：熱鍋加少許油，先下洋蔥絲與蒜末炒至軟甜透明，再加入牛肉片炒至半熟。\n3. 燉煮：放入馬鈴薯塊、紅蘿蔔塊與蒟蒻絲，倒入 500ml 水及所有調味料（醬油、味醂、米酒、糖、烹大師）。\n4. 熟化入味：大火煮滾後轉中小火，蓋上鍋蓋燉煮約 15～20 分鐘至馬鈴薯可用筷子輕鬆穿透。\n5. 盛盤：起鍋前撒上蔥花與七味粉即可熱騰騰享用。\n\n💡 廚神小撇步\n- 馬鈴薯切塊後可先泡水去除表面澱粉，燉煮時湯頭較不易混濁。\n- 煮好後靜置放涼再加熱食用，馬鈴薯與肉片會吸飽醬汁更為入味。",
