      "author": "未知",
      "source": "https://www.instagram.com/reel/DbxsssUPKM6/",
      "ingredients": "### 主料\n* 大杏鮑菇 2 支\n* 嫩煎牛肉片（或牛小排肉片） 200g",
      "summary": "杏鮑菇乾炒牛河 以杏鮑菇削薄片替代河粉的低卡創新乾炒牛河！杏鮑菇片的滑順彈牙與嫩煎牛肉片的鮮嫩相互呼應，在大火爆炒下裹滿濃郁醬香與鑊氣，風味甚至比傳統河粉更加爽口誘人。 🥣 食材清單 主料 大杏鮑菇 2 支 嫩煎牛肉片（或牛小排肉片） 200g 牛肉醃料 薄鹽醬油 1 大匙 蠔油 1 茶匙 鹽 少許...",
      "content": "# 杏鮑菇乾炒牛河\n\n以杏鮑菇削薄片替代河粉的低卡創新乾炒牛河！杏鮑菇片的滑順彈牙與嫩煎牛肉片的鮮嫩相互呼應，在大火爆炒下裹滿濃郁醬香與鑊氣，風味甚至比傳統河粉更加爽口誘人。\n\n## 🥣 食材清單\n\n### 主料\n* 大杏鮑菇 2 支\n* 嫩煎牛肉片（或牛小排肉片） 200g\n\n### 牛肉醃料\n* 薄鹽醬油 1 大匙\n* 蠔油 1 茶匙\n* 鹽 少許\n* 糖 少許\n* 米酒 1 茶匙\n* 水 1 大匙（打水鎖嫩）\n\n### 調味料與炒油\n* 食用油 適量\n* 醬油（或老抽） 1 大匙（大火嗆香用）\n\n## 🍳 製作步驟\n\n1. **處理杏鮑菇**：大杏鮑菇洗淨後，用削皮刀將杏鮑菇縱向削成薄長片（模擬河粉寬度與形狀）。\n2. **醃製牛肉**：牛肉片加入薄鹽醬油、蠔油、鹽、糖、米酒與 1 大匙水，用手抓捏至水分與醬汁完全被牛肉吸收（打水使肉質極致滑嫩）。\n3. **大火爆炒牛肉**：起熱鍋倒入適量油，放入醃好的牛肉片大火快速滑炒至 8 分熟，盛出備用。\n4. **大火乾炒合體**：原鍋下杏鮑菇片大火乾炒至微微軟化並釋放香氣，接著倒回牛肉片，沿鍋邊嗆入 1 大匙醬油，大火快速翻炒爆出鑊氣即可出鍋。\n\n## 💡 廚神小撇步\n\n* **削皮刀妙用**：使用削皮刀削出來的杏鮑菇薄片厚薄均勻，炒過後口感極為滑順，非常類似港式河粉。\n* **牛肉打水技巧**：醃肉時加入少許水份捏勻，能被肉纖維吸收，下鍋大火爆炒時不會流失水份，口感格外軟嫩。",
