      "author": "100lunchboxes",
      "source": "https://www.instagram.com/reel/DWOzXKsgI3V/?igsh=bXA0NXVrZzQ0MW85",
      "ingredients": "*   松阪豬 (豬頸肉)：280g",
      "summary": "氣炸味噌松阪豬 這是一道口感爽脆、醬香濃郁的氣炸鍋松阪豬料理。利用日式味噌、味醂與少許醬油調製黃金醃醬，塗抹在切花戳洞的松阪豬（黃金六兩肉）上醃漬入味，再經由氣炸鍋分段溫度烘烤，烤至表面呈現油亮微焦的琥珀焦糖色。經過靜置鎖汁後逆紋切片，入口外脆內彈，是一道極佳的便當主菜。 食材 松阪豬 豬頸肉：28...",
      "content": "# 氣炸味噌松阪豬\n\n這是一道口感爽脆、醬香濃郁的氣炸鍋松阪豬料理。利用日式味噌、味醂與少許醬油調製黃金醃醬，塗抹在切花戳洞的松阪豬（黃金六兩肉）上醃漬入味，再經由氣炸鍋分段溫度烘烤，烤至表面呈現油亮微焦的琥珀焦糖色。經過靜置鎖汁後逆紋切片，入口外脆內彈，是一道極佳的便當主菜。\n\n## 食材\n\n*   松阪豬 (豬頸肉)：280g\n\n## 秘製味噌醃醬\n\n*   味噌：1.5 大匙\n*   味醂：1 大匙\n*   醬油：0.5 大匙\n*   砂糖：1 小匙\n*   水：1 大匙\n\n## 步驟\n\n1.  **豬肉前置處理**：用紙巾將松阪豬表面的水分徹底擦乾。使用鐵叉在松阪豬的兩面均勻戳出細孔，以方便醃醬快速穿透肉質內部。\n2.  **醃製入味**：將味噌、味醂、醬油、糖與水充分攪拌均勻調成醃醬。將醃醬均勻塗抹在松阪豬兩面，放入保鮮袋或容器中密封，置於冰箱冷藏醃製 1 小時以上（醃隔夜更入味）。\n3.  **分段氣炸**：氣炸鍋預熱至 **180°C**。*（💡Tips：下鍋氣炸前，若想要口味較清淡，可用刮刀將松阪豬表面多餘的味噌醃醬稍微刮除，可防止表面過快焦黑）*。將松阪豬放入氣炸鍋中，以 **180°C 氣炸 15 分鐘**，中途（約 7-8 分鐘時）打開翻面一次。\n4.  **高溫上色**：15 分鐘後，將氣炸鍋溫度調高至 **200°C，繼續氣炸 3 分鐘**，直到表面呈現焦香亮麗的琥珀色，即可出爐。\n5.  **靜置與切片**：出爐後，將松阪豬放在砧板上**靜置 3 分鐘**以鎖住肉汁。隨後將刀子拿斜，**逆著豬肉的紋理**切成薄片（逆紋切能破壞纖維，讓口感最為脆口且容易咬斷），盛盤即可享用。\n\n## 料理筆記\n\n*   松阪豬本身油脂豐富且質地脆彈，非常適合氣炸或炙烤。戳洞能保證味噌醃醬深入肉裡，否則味噌因分子大不容易入味。\n*   烤完一定要「靜置」，如果一出爐立刻切，肉汁會瞬間流失，導致口感變乾。",
