      "ingredients": "### 主料\n- 玉米筍：1 包（約 10-12 根）\n- 蝦滑：1 條（約 150 公克）",
      "summary": "氣炸玉米筍夾蝦滑 「氣炸玉米筍夾蝦滑」是一道備料不用三分鐘、口感卻讓人大為驚豔的創意輕食。將清甜爽脆的玉米筍對半切開，中間擠入鮮甜軟 Q 的蝦滑做成夾心。送入氣炸鍋中，噴上少許食用油，出爐後撒上椒鹽與紅椒粉。咬下去的瞬間，一邊是玉米筍喀嚓的爽脆，一邊是蝦滑的鮮嫩彈牙，口感層次極佳，清爽美味無負擔。 ...",
      "content": "# 氣炸玉米筍夾蝦滑\n\n「氣炸玉米筍夾蝦滑」是一道備料不用三分鐘、口感卻讓人大為驚豔的創意輕食。將清甜爽脆的玉米筍對半切開，中間擠入鮮甜軟 Q 的蝦滑做成夾心。送入氣炸鍋中，噴上少許食用油，出爐後撒上椒鹽與紅椒粉。咬下去的瞬間，一邊是玉米筍喀嚓的爽脆，一邊是蝦滑的鮮嫩彈牙，口感層次極佳，清爽美味無負擔。\n\n## 🥣 食材清單\n\n### 主料\n- 玉米筍：1 包（約 10-12 根）\n- 蝦滑：1 條（約 150 公克）\n\n### 🧂 調味料 & 配料\n- 噴霧食用油：少許\n- 椒鹽粉：適量\n- 紅椒粉（可選）：少許\n\n## 🍳 製作步驟\n\n1. **處理玉米筍**：\n   將玉米筍用清水洗淨，用廚房紙巾徹底擦乾水分。用刀將玉米筍橫向對半切開（切成兩瓣長條狀）。\n2. **製作蝦滑夾心**：\n   取其中一片玉米筍，在切面上擠上適量的蝦滑（可以稍微擠厚一點），然後蓋上另一片玉米筍，像夾心餅乾一樣把它們夾起來，用手指輕輕壓一下，使玉米筍與蝦滑黏緊合體。\n3. **氣炸準備**：\n   在氣炸鍋的籃底鋪上一張烘焙紙，在烘焙紙表面噴上少許食用油。將做好的玉米筍蝦滑夾心整齊排列在紙上。\n4. **噴油氣炸**：\n   在玉米筍夾的表面也噴上一點點的食用油。送入氣炸鍋，設定 **180度 烤 15 分鐘**。\n5. **調味裝盤**：\n   烤至玉米筍微乾縮且蝦滑熟透呈微金黃色後出爐。撒上適量的椒鹽粉以及紅椒粉點綴色澤與香氣，即可擺盤享用。\n\n## 💡 廚神小撇步\n- **蝦滑哪裡買？**：蝦滑可以在全聯、火鍋料專賣店或海鮮市場買到袋裝或盒裝的，有些直接設計成可以用手擠的袋裝，操作起來非常方便。\n- **防止散開的技巧**：玉米筍表面一定要擦乾，否則多餘的水分會降低蝦滑的黏著度。夾心做好後稍微輕壓，讓蝦滑貼合玉米筍，氣炸時便不容易散開。\n- **風味變化**：如果不加椒鹽和紅椒粉，也可以在出爐後擠上一點美乃滋，或者沾泰式酸辣醬，風味同樣非常棒。",
