      "author": "lydia0622",
      "source": "https://www.instagram.com/reel/DYoGrqUhzCN/",
      "ingredients": "*   豬肋小排：550g\n*   蔥花：適量 (依個人喜好)",
      "summary": "氣炸蒜香排骨 這是一道週末歡樂時光必備的快手免油炸料理。使用豬肋小排，搭配肯私廚「黎巴嫩七香粉」增添獨特的肉桂與丁香層次感，再丟入氣炸鍋輕鬆完成。外表金黃微焦，內裡肉質扎實多汁，是一道讓人一塊接一塊的吮指異國風味美味。 食材 豬肋小排：550g 蔥花：適量 依個人喜好 醃料與調味料 醬油：1.5 匙...",
      "content": "# 氣炸蒜香排骨\n\n這是一道週末歡樂時光必備的快手免油炸料理。使用豬肋小排，搭配肯私廚「黎巴嫩七香粉」增添獨特的肉桂與丁香層次感，再丟入氣炸鍋輕鬆完成。外表金黃微焦，內裡肉質扎實多汁，是一道讓人一塊接一塊的吮指異國風味美味。\n\n## 食材\n\n*   豬肋小排：550g\n*   蔥花：適量 (依個人喜好)\n\n## 醃料與調味料\n\n*   醬油：1.5 匙\n*   蠔油：1 匙\n*   米酒：1 匙\n*   蒜末：適量\n*   糖：少許\n*   玉米粉 (或太白粉)：1 匙\n*   黎巴嫩七香粉 (或五香粉)：適量\n*   霹靂霹靂辣椒粉 (或一般辣椒粉)：適量 (依個人喜好)\n\n## 步驟\n\n1.  **醃製排骨**：將豬肋小排洗淨後用廚房紙巾徹底擦乾水分。放入碗中，加入醬油 1.5 匙、蠔油 1 匙、米酒 1 匙、適量蒜末、少許糖、玉米粉 1 匙及適量的黎巴嫩七香粉（或五香粉），用手抓勻按摩，讓每塊排骨均勻裹上醃料與粉漿，靜置醃漬 30 分鐘以上入味。\n2.  **排入氣炸鍋**：將醃製好的排骨平鋪於氣炸鍋的烘烤網上，儘量不要重疊，以確保受熱與氣流均勻。\n3.  **氣炸烘烤**：以 180°C 氣炸約 12-15 分鐘，中途拉出氣炸鍋將排骨翻面一次；最後將溫度調高至 200°C 氣炸 3 分鐘，使排骨表面呈現焦香金黃色澤並逼出多餘油脂，即可起鍋。\n4.  **調味盛盤**：出爐後撒上適量蔥花與依個人喜好撒上霹靂霹靂辣椒粉，抓勻後盛盤即可趁熱享用。\n\n## 料理筆記\n\n*   肯私廚的黎巴嫩七香粉帶有淡淡的肉桂與丁香香氣，能讓豬排骨展現濃郁的異國情調；若偏好傳統台式熱炒風味，亦可直接使用五香粉代替。\n*   醃料中加入一匙玉米粉或太白粉能幫助鎖住肉汁，並在排骨表面形成一層極薄的酥皮。\n*   每台氣炸鍋的火力與排骨的厚薄度不同，氣炸時間可依實際熟度與上色狀況進行微調。",
