      "author": "未知",
      "source": "https://www.instagram.com/reel/DUo4vKOjIDw/?igsh=aWFvOWFvc3RqczBo",
      "ingredients": "### 主料\n- 蘿蔔糕：1 條（切一口大小）\n- 蒜苗：1 根（斜切片）",
      "summary": "沙茶氣炸蘿蔔糕 炒蘿蔔糕也可以不用開火！這道「沙茶氣炸蘿蔔糕」利用氣炸鍋將蘿蔔糕炸得外酥內軟，再利用餘溫與剩餘空間爆香蒜苗、沙茶醬與醬油膏。簡單搖晃拌勻，就能做出一盤色香味俱全、沾滿香濃沙茶醬汁的台式炒蘿蔔糕，做法快速且免除油煙，是極佳的懶人午餐或宵夜選擇。 🥣 食材清單 主料 蘿蔔糕：1 條（切一...",
      "content": "# 沙茶氣炸蘿蔔糕\n\n炒蘿蔔糕也可以不用開火！這道「沙茶氣炸蘿蔔糕」利用氣炸鍋將蘿蔔糕炸得外酥內軟，再利用餘溫與剩餘空間爆香蒜苗、沙茶醬與醬油膏。簡單搖晃拌勻，就能做出一盤色香味俱全、沾滿香濃沙茶醬汁的台式炒蘿蔔糕，做法快速且免除油煙，是極佳的懶人午餐或宵夜選擇。\n\n## 🥣 食材清單\n\n### 主料\n- 蘿蔔糕：1 條（切一口大小）\n- 蒜苗：1 根（斜切片）\n\n### 調味料\n- 沙茶醬：1 大匙\n- 醬油膏：1 大匙\n- 食用油：1 大匙\n\n## 🍳 製作步驟\n\n1. **上油沾勻**：\n   在氣炸鍋的調理盒（或鋪了烘焙紙的炸籃）中先加入 1 大匙食用油，放入切好的一口大小蘿蔔糕，輕輕搖晃調理盒，讓每塊蘿蔔糕表面都均勻沾附一層薄薄的油。\n2. **第一階段氣炸（炸酥）**：\n   放入氣炸鍋，設定 **200度氣炸 15 分鐘**，直至蘿蔔糕外表呈現金黃酥脆的狀態。\n3. **加入調料爆香**：\n   將氣炸好的蘿蔔糕在調理盒內稍微推到一側移出空位，在空位中加入 1 大匙沙茶醬、1 大匙醬油膏以及切好的蒜苗片。\n4. **第二階段氣炸（炒香）**：\n   再次送回氣炸鍋，以 **200度氣炸 3 分鐘**，利用高溫將沙茶醬與蒜苗的香氣爆出。\n5. **拌勻起鍋**：\n   從氣炸鍋中取出調理盒，用耐熱夾子或以手輕輕搖晃調理盒，將沙茶醬汁與蘿蔔糕充分拌勻，讓每塊蘿蔔糕都沾滿醬汁，即可盛盤享用。\n\n## 💡 廚神小撇步\n- **均勻沾油的祕訣**：蘿蔔糕一定要先均勻沾上一層油再氣炸，這樣外皮才能炸出像油炸一樣的酥脆外殼，否則口感會過於乾硬。\n- **使用氣炸鍋調理盒**：使用帶底部的氣炸鍋專用調理盒（深烤盤）或耐高溫的矽膠烤盤，後面倒入沙茶醬與醬油膏時，醬汁才不會直接滴落漏到氣炸鍋底部。\n- **蒜苗的搭配**：蒜苗是這道菜的靈魂，氣炸 3 分鐘恰好能釋放出蒜香並保留鮮綠，與沙茶醬是非常經典的台式絕配。",
