      "source": "https://www.instagram.com/reel/DZuK_ECh8v7/",
      "ingredients": "*   雞肉 (雞胸肉或里肌肉)：約 300-400 克 (切條狀)\n*   青椒：1 顆 (去籽，切薄片)\n*   洋蔥：適量 (切絲或切丁)\n*   蒜末：適量",
      "summary": "沙茶青椒炒嫩雞 這是一道香氣濃郁且非常適合帶便當的常備菜。醃漬時加入沙茶醬與太白粉抓勻能完美鎖住肉汁，即使經過隔夜冷藏並用微波爐加熱，雞肉依然能保持鮮嫩不乾柴。 食材 雞肉 雞胸肉或里肌肉：約 300400 克 切條狀 青椒：1 顆 去籽，切薄片 洋蔥：適量 切絲或切丁 蒜末：適量 醃肉料 沙茶醬：...",
      "content": "# 沙茶青椒炒嫩雞\n\n這是一道香氣濃郁且非常適合帶便當的常備菜。醃漬時加入沙茶醬與太白粉抓勻能完美鎖住肉汁，即使經過隔夜冷藏並用微波爐加熱，雞肉依然能保持鮮嫩不乾柴。\n\n## 食材\n\n*   雞肉 (雞胸肉或里肌肉)：約 300-400 克 (切條狀)\n*   青椒：1 顆 (去籽，切薄片)\n*   洋蔥：適量 (切絲或切丁)\n*   蒜末：適量\n\n## 醃肉料\n\n*   沙茶醬：1 大匙\n*   柴魚醬油：1 大匙\n*   太白粉：1 小匙 (鎖水關鍵)\n\n## 調味料\n\n*   沙茶醬：1 大匙 (起鍋前增香用)\n\n## 步驟\n\n1.  **醃漬雞肉**：將雞肉切成條狀，置於碗中。加入沙茶醬 1 大匙、柴魚醬油 1 大匙以及太白粉 1 小匙，用手反覆抓勻至水分被雞肉吸收，放入冰箱醃漬一夜 (或至少醃漬 30 分鐘) 使其充分入味。\n2.  **爆香與煎肉**：熱油鍋，先放入洋蔥絲爆香至半透明，接著倒入醃好的雞肉條，以中火煎炒至雞肉表面變色且熟透，再加入蒜末快速翻炒出香氣。\n3.  **大火快炒青椒**：起鍋前一分鐘，放入青椒薄片，並再加入 1 大匙沙茶醬。轉大火快速翻炒，讓沙茶醬均勻裹覆在所有食材上，並使青椒稍微斷生。\n4.  **起鍋盛盤**：維持青椒的翠綠與清脆口感，翻炒均勻後即可立刻關火，盛盤享用。\n\n## 料理筆記\n\n*   青椒在起鍋前一分鐘才下，可以保持脆綠的外觀與清脆的口感，不會因為過度烹調而變黃變軟。\n*   起鍋前額外加入的一匙沙茶醬是靈魂，能補充因為煎炒而流失的沙茶香氣，讓味道更上一個層次。",
