      "author": "未知",
      "source": "https://www.instagram.com/reel/DQB7AjmgQvh/?igsh=MWZxMTFvdTk4eTQ1Zw==",
      "ingredients": "### 主料\n* 義大利麵：1 人份\n* 蝦仁：8-10 隻（去殼開背去泥腸）\n* 蒜頭：4 瓣（切成蒜末）",
      "summary": "白醬蝦仁義大利麵 這是一道近期吃過最好吃、做法又極其簡單的白醬蝦仁義大利麵。所有食材與醬汁均易於取得。利用奶油煎香的蝦仁，配上濃郁的白醬，更在醬汁中多加入一片起司，讓奶香味瞬間升級。是十分鐘就能完成的餐廳級美味。 🥣 食材清單 主料 義大利麵：1 人份 蝦仁：810 隻（去殼開背去泥腸） 蒜頭：4 ...",
      "content": "# 白醬蝦仁義大利麵\n\n這是一道近期吃過最好吃、做法又極其簡單的白醬蝦仁義大利麵。所有食材與醬汁均易於取得。利用奶油煎香的蝦仁，配上濃郁的白醬，更在醬汁中多加入一片起司，讓奶香味瞬間升級。是十分鐘就能完成的餐廳級美味。\n\n## 🥣 食材清單\n\n### 主料\n* 義大利麵：1 人份\n* 蝦仁：8-10 隻（去殼開背去泥腸）\n* 蒜頭：4 瓣（切成蒜末）\n\n### 醃料\n* 鹽：少許\n\n### 調味料\n* 奶油：15 克\n* 市售白醬：1 大碗\n* 起司片：1 片\n* 黑胡椒或羅勒碎：少許（點綴用）\n\n## 🍳 製作步驟\n\n1. **醃製蝦仁**：將蝦仁清洗乾淨，擦乾，開背並取出泥腸。撒上少許鹽大略抓勻醃製。\n2. **煮義大利麵**：煮一鍋熱水，加入一小匙鹽，下入義大利麵，煮至約 8 分熟（麵心微硬），撈起瀝乾備用。\n3. **煎香蝦仁**：熱鍋放入奶油融化，將醃好的蝦仁放入鍋中煎至兩面變色、稍微熟透後，盛出備用。\n4. **爆香蒜末**：利用鍋內餘下的奶油，放入蒜末以小火慢炒出香氣。\n5. **熬煮白醬**：倒入市售白醬，隨即放入一片起司片，慢慢攪拌至起司融化、與白醬完全融合，增加醬汁的香醇度。\n6. **拌炒盛盤**：將煮好的義大利麵和煎熟的蝦仁通通擺入白醬鍋中，快速拌炒均勻，使麵條吸附滿滿的白醬。盛出裝盤後，撒上些許黑胡椒或羅勒碎點綴即可。\n\n## 💡 廚神小撇步\n\n* **白醬升級秘訣**：在市售白醬中多加入「一片起司片」一起融化，是讓白醬風味變得極其濃郁、擁有餐廳級質感的美味關鍵。\n* **保持蝦仁嫩度**：蝦仁不要一直在醬汁中煮，先用奶油煎至 8 分熟撈出，等麵與醬汁混勻時再放回去快速拌炒，蝦肉才會脆彈多汁。",
