      "ingredients": "### 主料\n*   青江菜：1 包 (約 3-4 株)\n*   蒜頭：2-3 瓣 (切末或使用現成蒜蓉醬)",
      "summary": "直切脆甜炒青江菜 許多人覺得青江菜帶有一種特殊的「瓦斯味」或苦味，其實只要改變切法，就能讓青江菜變得驚人甜美！採用「順著纖維直切」的方式，不僅能保持青江菜的爽脆，還能鎖住蔬菜本糖分，蒜炒後鮮甜可口。 🥣 食材清單 主料 青江菜：1 包 約 34 株 蒜頭：23 瓣 切末或使用現成蒜蓉醬 調味料 食用...",
      "content": "# 直切脆甜炒青江菜\n\n許多人覺得青江菜帶有一種特殊的「瓦斯味」或苦味，其實只要改變切法，就能讓青江菜變得驚人甜美！採用「順著纖維直切」的方式，不僅能保持青江菜的爽脆，還能鎖住蔬菜本糖分，蒜炒後鮮甜可口。\n\n## 🥣 食材清單\n\n### 主料\n*   青江菜：1 包 (約 3-4 株)\n*   蒜頭：2-3 瓣 (切末或使用現成蒜蓉醬)\n\n### 調味料\n*   食用油：1 大匙\n*   鹽：少許\n*   水：少許 (審煮用)\n\n## 🍳 製作步驟\n\n1.  **直切處理**：將青江菜徹底洗淨泥沙。將每株青江菜由根部往葉片方向「直向剖半」或切成四等份條狀（順著纖維切），不要橫切切段。\n2.  **爆香蒜頭**：熱鍋下 1 大匙油，放入蒜末爆香至香氣飄出。\n3.  **大火翻炒**：放入直切好的青江菜，轉大火快速翻炒，讓青江菜均勻裹上蒜油。\n4.  **燜煮與調味**：沿鍋邊加入少許水，立刻蓋上鍋蓋，以大火燜煮約 30-40 秒（這樣可以讓莖部快速熟化且保持脆綠）。開蓋，撒入少許鹽調味，快速翻炒幾下即可出鍋。\n\n## 💡 廚神小撇步\n*   **為什麼要直切**：橫切會切斷青江菜的植物纖維，容易釋放出令人不悅的「瓦斯味」與苦味物質。而直切（順著纖維）則能保留植物細胞的完整性，鎖住甜味並帶來極致的爽脆口感。\n*   **大火燜炒**：青江菜的莖部較厚，大火加蓋燜煮可以利用高溫蒸氣快速將莖部蒸熟，同時避免葉片因過度翻炒而變黑變爛。",
