      "content": "# 破布子蒸魚片豆腐\n\n絕不錯過wanshiruyi.kitchen的任何貼文 註冊 Instagram，隨時掌握最新消息。\n\n🥣 食材清單\n  * **主料**：• 七星鱸魚排 1 片、• 板豆腐 1 盒、⁡、❍ 蒸料、• 味醂 1 大匙、• 鹽 1/4 小匙、• 薑絲 少許、⁡、❍ 淋醬\n  * **調味料**：晚餐不知道要煮什麼？、就來試試這道破布子蒸魚片豆腐吧！、⁡、———————————————、⁡、• 醬油 1 大匙、• 味醂 1/2 大匙、• 水 1 大匙、• 白胡椒 少許、❍ 裝飾＆熱油\n\n🍳 製作步驟\n1. ❶ 豆腐切片鋪底，擺上畫刀的鱸魚排，放上蒸料，大火蒸 8 分鐘。\n2. ❷ 出爐後把盤底的蒸魚水倒掉。\n3. ❸ 淋上調好的【淋醬】，再蒸5分鐘，出鍋鋪上蔥絲，澆上滾燙的【芝麻油】激發香氣即完成！\n4. kehan0523\n5. 天\n6. 微滾水煮比蒸的還好吃\n7. 個讚\n8. 回覆\n9. jim9.23oooo\n10. 天\n11. 個讚\n12. 回覆\n\n💡 廚神小撇步\n  * 可依個人口味調整調味料用量，控制火候以維持良好口感。",
