      "ingredients": "* **主料**：豬絞肉300g、牛絞肉300g、用調理機打碎：、紅蘿蔔半根、芹菜3-4根、洋蔥半顆、墨西哥辣椒適量（可省）、但有加香氣很讚👍、蒜碎 4-5瓣\n  * **調味料**：牙膏式蕃茄糊（2-3匙）、高湯包（茅乃舍野菜）、咖哩塊（中辛）可以自己選不辣的、攪拌煮10分鐘（中火即可）、完成！、#乾咖哩 #蕃茄咖哩、cchenyijin、2週、請問墨西哥辣椒去那買、讚",
