      "content": "# 蕃茄乾式咖哩肉醬\n\n絕不錯過a_wen_kitchen的任何貼文 註冊 Instagram，隨時掌握最新消息。\n\n🥣 食材清單\n  * **主料**：豬絞肉300g、牛絞肉300g、用調理機打碎：、紅蘿蔔半根、芹菜3-4根、洋蔥半顆、墨西哥辣椒適量（可省）、但有加香氣很讚👍、蒜碎 4-5瓣\n  * **調味料**：牙膏式蕃茄糊（2-3匙）、高湯包（茅乃舍野菜）、咖哩塊（中辛）可以自己選不辣的、攪拌煮10分鐘（中火即可）、完成！、#乾咖哩 #蕃茄咖哩、cchenyijin、2週、請問墨西哥辣椒去那買、讚\n\n🍳 製作步驟\n1. 肉炒香氣出來（也可以加牛油增加香氣）\n2. 放入蔬菜炒出甜味5分鐘\n\n💡 廚神小撇步\n  * 可依個人口味調整調味料用量，控制火候以維持良好口感。",
