      "source": "https://www.instagram.com/reel/DTh_C-0gE_V/?igsh=dHoxNXVsamw2cDV2",
      "ingredients": "### 主料\n- 澎湖土魠魚輪切片（或其他魚排如鮭魚、鱈魚）：1 片（約 300 克）\n- 鹽巴：少許（下處理去腥用）",
      "summary": "西京燒氣炸土魠魚 「西京燒」是日本高級料亭常見的經典魚料理，傳統上使用甘甜的西京白味噌塗抹醃製後烤熟。這道食譜將冬季限定、肥美細緻的澎湖白金土魠魚，與經典西京漬醬汁結合，並利用氣炸鍋快速烘烤。烤好的魚肉外層散發著微微的味噌焦香，內部細緻鮮甜、油脂飽滿，是一道奢華又極其簡單的日式家庭料理。 🥣 食材清...",
      "content": "# 西京燒氣炸土魠魚\n\n「西京燒」是日本高級料亭常見的經典魚料理，傳統上使用甘甜的西京白味噌塗抹醃製後烤熟。這道食譜將冬季限定、肥美細緻的澎湖白金土魠魚，與經典西京漬醬汁結合，並利用氣炸鍋快速烘烤。烤好的魚肉外層散發著微微的味噌焦香，內部細緻鮮甜、油脂飽滿，是一道奢華又極其簡單的日式家庭料理。\n\n## 🥣 食材清單\n\n### 主料\n- 澎湖土魠魚輪切片（或其他魚排如鮭魚、鱈魚）：1 片（約 300 克）\n- 鹽巴：少許（下處理去腥用）\n\n### 🇯🇵 西京漬黃金醬汁（基本比例 2:1:1）\n- 白味噌（推薦日式甘口白味噌/西京味噌）：2 大匙\n- 味醂：1 大匙\n- 日本清酒（或米酒）：1 大匙\n- 砂糖（可選）：1 小匙（若喜歡偏甜口感可加）\n\n## 🍳 製作步驟\n\n1. **魚肉去腥（下處理）**：\n   土魠魚片完全解凍，兩面薄薄地撒上一層鹽巴，靜置 15 - 20 分鐘。等魚肉表面析出水分後，用廚房紙巾**徹底擦乾水分與血水**（這一步能帶走腥味並使肉質更緊實）。\n2. **調製西京漬醬汁**：\n   在碗中將白味噌 2 大匙、味醂 1 大匙、清酒 1 大匙和砂糖 1 小匙混合，充分攪拌至均勻滑順無顆粒。\n3. **塗抹醃製**：\n   將調好的西京漬醬汁均勻塗抹在土魠魚兩面。將魚片裝入夾鏈袋或保鮮盒中，放進冰箱**冷藏醃製至少 6 小時，或醃製隔夜會更加入味**。\n4. **烤前處理**：\n   準備烤製前將魚片取出。**用廚房紙巾輕輕將魚片表面多餘的味噌醬抹掉**（保留薄薄一層即可，多餘的味噌在高溫下非常容易烤焦）。\n5. **氣炸烘烤**：\n   氣炸鍋鋪上烘焙紙，放入土魠魚片。設定 **170°C 氣炸 15 分鐘**（300克規格的烤法，若魚肉較厚或較重，可適度延長 2 - 3 分鐘），中途不需要翻面，氣炸至表面呈現微焦黃色且熟透即可。\n6. **盛盤**：\n   小心取出裝盤，可配上一瓣檸檬或幾片嫩薑片點綴。\n\n## 💡 廚神小撇步\n- **為什麼一定要擦掉表面味噌？**：西京味噌含有大量糖分與味醂，非常容易燒焦。下鍋前如果不將表面多餘的味噌拭去，會導致魚肉內部還沒熟，外層就已經焦黑碳化。\n- **適用多種魚類**：此西京漬做法是經典的日本料理萬能公式，除了土魠魚，也非常適合用來製作西京燒鮭魚、鱈魚或圓鱈。\n- **烤箱版本**：若使用烤箱，可設定 200°C 烤約 12-15 分鐘至表面上色。",
