      "ingredients": "- **主料**：\n  - 鮭魚排 1-2塊\n- **醃醬調味料（黃金比例 3:1:1）**：\n  - 十全味噌（或白味噌）3大匙\n  - 味醂 1大匙\n  - 清酒（或米酒）1大匙\n  - 鹽 少許（預處理用）",
      "summary": "西京燒鮭魚 「西京燒」是日本經典的醬醃烤魚料理，將鮮美脂香濃郁的鮭魚以黃金比例味噌醃醬浸漬過夜，鹹甜回甘、香醇入味，氣炸或乾煎都極具日式料亭風味！ 🥣 食材清單 主料： 鮭魚排 12塊 醃醬調味料（黃金比例 3:1:1）： 十全味噌（或白味噌）3大匙 味醂 1大匙 清酒（或米酒）1大匙 鹽 少許（預...",
      "content": "# 西京燒鮭魚\n\n「西京燒」是日本經典的醬醃烤魚料理，將鮮美脂香濃郁的鮭魚以黃金比例味噌醃醬浸漬過夜，鹹甜回甘、香醇入味，氣炸或乾煎都極具日式料亭風味！\n\n🥣 食材清單\n- **主料**：\n  - 鮭魚排 1-2塊\n- **醃醬調味料（黃金比例 3:1:1）**：\n  - 十全味噌（或白味噌）3大匙\n  - 味醂 1大匙\n  - 清酒（或米酒）1大匙\n  - 鹽 少許（預處理用）\n\n🍳 製作步驟\n1. 鮭魚表面均勻撒上一點鹽，靜置5分鐘去腥並釋出多餘水分。\n2. 調配醃醬：將十全味噌、味醂與清酒以 3：1：1 的黃金比例混合均勻。\n3. 將鮭魚表面的水分用廚房紙巾徹底擦乾，再均勻塗抹上醃漬味噌醬，裝入保鮮袋或容器放入冰箱冷藏醃漬一晚上。\n4. 隔天從冰箱取出後，用廚房紙巾將鮭魚表面的味噌醬稍微擦拭乾淨（避免下鍋容易焦黑）。\n5. 放入平底鍋中小火乾煎或放入氣炸鍋/烤箱烤至熟透，表面帶有微微焦香即可食用。\n\n💡 廚神小撇步\n- 味噌醬極易焦黑，下鍋前一定要將表面多餘的醬汁擦乾或拭去。\n- 傳統多用日式甘味白味噌，若家中使用一般十全味噌，此 3:1:1 配方同樣風味極佳且富含甘甜酒香。",
