      "ingredients": "- **主料**：\n  - 澳洲小馬鈴薯（Baby Potatoes）適量（切塊）\n- **調味料**：\n  - 鹽 少許\n  - 洋蔥粉（Onion Powder）適量\n  - 海苔粉（Aonori）適量\n- **蘸醬**：\n  - 辣味美乃滋 / 辣抹醬 適量",
      "summary": "酥炸馬鈴薯 外皮金黃香酥、內裡鬆軟綿密的酥炸馬鈴薯塊！撒上洋蔥粉與海苔粉，香氣撲鼻，搭配辣味美乃滋蘸醬，令人一口接一口停不下來！ 🥣 食材清單 主料： 澳洲小馬鈴薯（Baby Potatoes）適量（切塊） 調味料： 鹽 少許 洋蔥粉（Onion Powder）適量 海苔粉（Aonori）適量 蘸醬...",
      "content": "# 酥炸馬鈴薯\n\n外皮金黃香酥、內裡鬆軟綿密的酥炸馬鈴薯塊！撒上洋蔥粉與海苔粉，香氣撲鼻，搭配辣味美乃滋蘸醬，令人一口接一口停不下來！\n\n🥣 食材清單\n- **主料**：\n  - 澳洲小馬鈴薯（Baby Potatoes）適量（切塊）\n- **調味料**：\n  - 鹽 少許\n  - 洋蔥粉（Onion Powder）適量\n  - 海苔粉（Aonori）適量\n- **蘸醬**：\n  - 辣味美乃滋 / 辣抹醬 適量\n\n🍳 製作步驟\n1. 澳洲小馬鈴薯洗淨切適口小塊。\n2. 放入油鍋中炸至表面呈現金黃酥脆後撈出瀝油。\n3. 趁熱撒上鹽、洋蔥粉及海苔粉，均勻翻拌讓每塊馬鈴薯都裹滿調味粉。\n4. 裝盤後附上辣味美乃滋，蘸著享用即可。\n\n💡 廚神小撇步\n- 剛出油鍋趁熱撒上洋蔥粉與海苔粉，調味粉更容易吸附在馬鈴薯表面。",
