      "author": "未知",
      "source": "https://www.instagram.com/reel/DbxxZ2_JBIO/",
      "ingredients": "### 主料\n* 虱目魚肚 1 片\n* 醃瓜仔（醬瓜） 適量\n* 蔥段 適量\n* 薑絲 適量\n* 九層塔 1 把",
      "summary": "醃瓜仔虱目魚 鹹香回甘的古早味醃瓜仔，配上煎得恰恰香酥的虱目魚肚！醃瓜口感ㄎㄠˊㄎㄠˊ脆口，帶有天然的甘甜與鹹香，與鮮美的虱目魚完美融合，是極具代表性的台式經典家常菜。 🥣 食材清單 主料 虱目魚肚 1 片 醃瓜仔（醬瓜） 適量 蔥段 適量 薑絲 適量 九層塔 1 把 調味料 醬油 1 大匙 水 適...",
      "content": "# 醃瓜仔虱目魚\n\n鹹香回甘的古早味醃瓜仔，配上煎得恰恰香酥的虱目魚肚！醃瓜口感ㄎㄠˊㄎㄠˊ脆口，帶有天然的甘甜與鹹香，與鮮美的虱目魚完美融合，是極具代表性的台式經典家常菜。\n\n## 🥣 食材清單\n\n### 主料\n* 虱目魚肚 1 片\n* 醃瓜仔（醬瓜） 適量\n* 蔥段 適量\n* 薑絲 適量\n* 九層塔 1 把\n\n### 調味料\n* 醬油 1 大匙\n* 水 適量\n* 白胡椒粉 適量\n\n## 🍳 製作步驟\n\n1. **煎香虱目魚**：熱鍋後免放油（虱目魚肚本身油脂豐富），將虱目魚肚下鍋，以中火煎約 5–7 分鐘至兩面呈現金黃酥脆。\n2. **下辛香料與醃瓜**：將魚肉翻面，放入蔥段、薑絲與切塊的醃瓜仔，一起拌炒約 5 分鐘釋放香氣。\n3. **紅燒悶煮**：加入 1 大匙醬油與適量水，蓋上鍋蓋悶燒幾分鐘讓魚肉吸收醬汁與醃瓜的甘甜。\n4. **起鍋調味**：起鍋前撒上少許白胡椒粉並放入一把九層塔，翻炒至九層塔香味溢出即可盛盤。\n\n## 💡 廚神小撇步\n\n* **煎魚不黏鍋與無油煎**：虱目魚肚脂肪豐富，冷鍋或熱鍋直接皮朝下煎即可逼出魚油，免外加油脂。\n* **醃瓜風味關鍵**：醃瓜仔自帶鹹甘味，醬油用量不宜過多，以免掩蓋魚肉與醃瓜的自然鮮甘。",
