      "ingredients": "### 主料\n*   鯽魚：1-2 條 (洗淨，用廚房紙巾吸乾水分)\n*   蔥：大量 (切蔥段，蔥綠與蔥白分開)\n*   薑：適量 (切片)\n*   大蒜：數瓣 (整瓣)",
      "summary": "醋燜鯽魚 這是一道做法傳統、極其開胃的醋燜鯽魚。利用慢火长时间醋燜，不僅能去腥提鮮，還能將鯽魚細小的魚刺燜至酥軟，愛吃酸的您一定會愛上這道料理。 🥣 食材清單 主料 鯽魚：12 條 洗淨，用廚房紙巾吸乾水分 蔥：大量 切蔥段，蔥綠與蔥白分開 薑：適量 切片 大蒜：數瓣 整瓣 調味料 烏醋或香醋：2 ...",
      "content": "# 醋燜鯽魚\n\n這是一道做法傳統、極其開胃的醋燜鯽魚。利用慢火长时间醋燜，不僅能去腥提鮮，還能將鯽魚細小的魚刺燜至酥軟，愛吃酸的您一定會愛上這道料理。\n\n## 🥣 食材清單\n\n### 主料\n*   鯽魚：1-2 條 (洗淨，用廚房紙巾吸乾水分)\n*   蔥：大量 (切蔥段，蔥綠與蔥白分開)\n*   薑：適量 (切片)\n*   大蒜：數瓣 (整瓣)\n\n### 調味料\n*   烏醋或香醋：2 大匙\n*   醬油：適量\n*   米酒：適量\n*   砂糖：少許\n*   熱水：適量\n\n## 🍳 製作步驟\n\n1.  **煎魚**：熱鍋下油，將鯽魚放入鍋中，以中小火慢煎至兩面呈金黃色，盛出備用。\n2.  **爆香配料**：利用鍋中餘油，放入薑片、整瓣大蒜與蔥白部分慢火煸香。\n3.  **放入魚與下調料**：將煎好的鯽魚重新鋪回鍋內。沿鍋邊熗入米酒，接著加入烏醋（或香醋）兩大匙、適量醬油與少許砂糖，加入適量熱水（淹過魚身大半）。\n4.  **慢火燜煮**：蓋上鍋蓋，轉小火慢慢燜煮約 50 分鐘，使醋香充分滲透，並讓小魚刺軟化。\n5.  **出鍋**：開蓋，轉大火稍微收汁，最後放入蔥綠段翻炒數下至變軟，即可起鍋裝盤。\n\n## 💡 廚神小撇步\n*   **醋的用量**：這道菜的重點在於「醋燜」，兩大匙的烏醋或香醋能與魚肉蛋白反應，軟化細小魚刺，同時提供醇厚的酸甜回甘，請不要害怕放醋。\n*   **煎魚吸乾水分**：煎魚前一定要將魚身表面的水分完全吸乾，否則下鍋容易脫皮且油爆。",
