      "author": "未知",
      "source": "https://www.instagram.com/reel/DT74K9JDows/?igsh=MThsNmNnM3JtbnpucQ==",
      "ingredients": "### 主料\n- 雞翅（二節翅）：1 斤（約 500-600 克）",
      "summary": "金沙焗雞翅 這道「金沙焗雞翅（鹹蛋黃焗雞翅）」是大人小孩都無法抗拒的人氣好菜。雞翅先醃製入味，裹上一層極薄的澱粉，以中小火慢煎至外皮金黃酥脆、內裡鮮嫩多汁。最後裹上一層濃郁起沙、鹹甜交織的黃金鹹蛋黃醬，入口鹹香酥脆，美味到讓人忍不住舔手指！ 🥣 食材清單 主料 雞翅（二節翅）：1 斤（約 50060...",
      "content": "# 金沙焗雞翅\n\n這道「金沙焗雞翅（鹹蛋黃焗雞翅）」是大人小孩都無法抗拒的人氣好菜。雞翅先醃製入味，裹上一層極薄的澱粉，以中小火慢煎至外皮金黃酥脆、內裡鮮嫩多汁。最後裹上一層濃郁起沙、鹹甜交織的黃金鹹蛋黃醬，入口鹹香酥脆，美味到讓人忍不住舔手指！\n\n## 🥣 食材清單\n\n### 主料\n- 雞翅（二節翅）：1 斤（約 500-600 克）\n\n### 🧂 醃料\n- 薑片：4-5 片\n- 蔥：1 根（切段）\n- 米酒（或料酒）：1 大匙\n- 醬油（生抽）：1 大匙\n- 蠔油：1 小匙\n- 鹽巴：少許\n- 胡椒粉：少許\n\n### 🍳 裹粉與金沙醬\n- 太白粉（或地瓜粉）：適量（裹薄粉用）\n- 鹹蛋黃醬（或熟鹹蛋黃 3-4 顆壓碎）：2 大匙\n- 白芝麻：少許（裝飾用）\n\n## 🍳 製作步驟\n\n1. **雞翅處理**：\n   雞翅洗淨並以廚房紙巾擦乾。在雞翅的**背面（沒有雞皮的那一面）縱向劃上一刀**（這能幫助雞翅快速入味，也更容易煎熟）。\n2. **醃製入味**：\n   將雞翅放入碗中，加入薑片、蔥段、米酒、醬油、蠔油、鹽巴與胡椒粉，用手抓拌均勻，醃製 **10 分鐘**。\n3. **拍上薄粉**：\n   將醃好的雞翅揀去蔥薑。把雞翅逐隻均勻裹上一層薄薄的太白粉，裹完後輕輕拍抖掉多餘的乾粉。\n   > [!TIP]\n   > 裹薄粉是雞翅能煎出酥脆外皮的關鍵，還能幫助後續的鹹蛋黃醬完美附著。\n4. **慢火煎熟**：\n   熱鍋倒入適量食用油，轉**中小火**放入雞翅，煎至一面金黃定型後翻面。全程慢煎約 8-10 分鐘，直到兩面呈現金黃酥脆且熟透，撈出瀝油備用。\n5. **慢火炒金沙**：\n   鍋中留少許底油，轉**小火**，放入 2 大匙鹹蛋黃醬（若使用鹹蛋黃泥則加入少許油慢炒），小火慢慢翻炒，直至鹹蛋黃融化、**起沙並冒出均勻細緻的白泡泡**。\n6. **快速裹醬**：\n   蛋黃醬起沙後，將煎好的雞翅倒回鍋中，**立即關火**。利用鍋子餘溫快速翻炒，讓每隻雞翅都均勻裹滿金黃的鹹蛋黃醬。\n7. **裝盤**：\n   起鍋盛盤，撒上少許白芝麻點綴即可上桌。\n\n## 💡 廚神小撇步\n- **雞翅背面劃刀的妙處**：雞翅的正面有一層厚雞皮，調味很難滲透。從背面劃一刀既不影響正面美觀，又能迅速入味、縮短煎熟的時間，防止雞肉煎過頭變柴。\n- **炒金沙切忌大火**：不論是市售鹹蛋黃醬還是自製鹹蛋黃泥，都含有糖與脂質，極易燒焦。炒製時一定要用最小火，炒到冒細密泡泡（起沙）就代表香氣完全激發了。\n- **關火裹醬的秘訣**：倒入雞翅後一定要先關火再翻炒。這能防止高溫繼續加熱使鹹蛋黃醬油水分離或焦黑，裹出來的「金沙衣」才會均勻漂亮。",
