      "source": "https://www.instagram.com/reel/DYwZUm-Tn79/",
      "ingredients": "### 主料\n*   絲瓜：1 條 (去皮切大塊)\n*   生豆皮：適量 (切成條狀)\n*   雞蛋：2 顆\n*   鹹蛋：1 顆 (切碎，蛋黃與蛋白可分開或一起切碎)",
      "summary": "金沙絲瓜燉生豆皮 這是一道健康、簡單又富有飽足感的絲瓜減脂料理。利用鹹蛋黃炒出金沙底，搭配水嫩的絲瓜與多汁的生豆皮，最後拌入滑嫩的煎蛋，口感層次分明，是減重時期的好選擇！ 🥣 食材清單 主料 絲瓜：1 條 去皮切大塊 生豆皮：適量 切成條狀 雞蛋：2 顆 鹹蛋：1 顆 切碎，蛋黃與蛋白可分開或一起切...",
      "content": "# 金沙絲瓜燉生豆皮\n\n這是一道健康、簡單又富有飽足感的絲瓜減脂料理。利用鹹蛋黃炒出金沙底，搭配水嫩的絲瓜與多汁的生豆皮，最後拌入滑嫩的煎蛋，口感層次分明，是減重時期的好選擇！\n\n## 🥣 食材清單\n\n### 主料\n*   絲瓜：1 條 (去皮切大塊)\n*   生豆皮：適量 (切成條狀)\n*   雞蛋：2 顆\n*   鹹蛋：1 顆 (切碎，蛋黃與蛋白可分開或一起切碎)\n\n### 調味料\n*   食用油：適量\n*   水：少許\n\n## 🍳 製作步驟\n\n1.  **食材前置**：絲瓜去皮後切成適口大塊。生豆皮切成條狀。將鹹蛋切得碎碎的備用。\n2.  **製作滑蛋**：熱油鍋，倒入打散的兩顆雞蛋液，快速用筷子推動炒成柔嫩的滑蛋，盛出備用。\n3.  **炒香金沙**：鍋中留底油，放入切碎的鹹蛋（尤其是蛋黃部分），用小火慢炒至起泡，呈現金黃色的金沙狀態。\n4.  **燜燉絲瓜與豆皮**：加入切好的絲瓜塊與生豆皮條，加入極少量的水（絲瓜本身會出水），蓋上鍋蓋燜煮約 5 分鐘，直到絲瓜變軟呈翠綠色。\n5.  **合炒滑蛋**：開蓋，將步驟 2 炒好的滑嫩煎蛋放入鍋中，與絲瓜和豆皮一起翻炒均勻，讓滑蛋吸飽絲瓜與金沙的湯汁即可出鍋。\n\n## 💡 廚神小撇步\n*   **不需額外加鹽**：這道菜完全利用了鹹蛋本身的鹹度，搭配絲瓜的清甜，因此不需要另外加鹽。\n*   **挑選絲瓜**：要挑選蒂頭（地頭）看起來綠色且新鮮、摸起來品質均勻、花蒂紋路還沒完全開展的絲瓜，口感最嫩、指（種子）最小。",
