      "author": "未知",
      "source": "https://www.instagram.com/reel/DTKrJormJOB/?igsh=MWRmYmV6cmhhenkzdA==",
      "ingredients": "### 主料\n- 板豆腐干：4 塊（先橫剖薄片，再切成細絲）\n- 豬里脊肉絲：150 克\n- 蒜頭：4-5 瓣（切蒜片，約 20 克）\n- 紅辣椒：1 根（去籽切細絲，約 15 克）\n- 青蔥：2 根（切長蔥絲，約 30 克）",
      "summary": "鑊香肉絲炒豆干 這道「鑊香肉絲炒豆干」是一道考驗熱炒基本功的經典下飯菜。很多人炒豆干常遇到「豆干水水的不入味」或「肉絲乾柴黏成一團」的問題。本食譜分享大廚傳授的關鍵一步——「乾煸豆干至微焦起皮」，利用熱能排出豆干內多餘水分，使其表面形成微細孔洞，如此在紅燒收汁時便能迅速吸飽醬香精華，做出外Q內嫩、香...",
      "content": "# 鑊香肉絲炒豆干\n\n這道「鑊香肉絲炒豆干」是一道考驗熱炒基本功的經典下飯菜。很多人炒豆干常遇到「豆干水水的不入味」或「肉絲乾柴黏成一團」的問題。本食譜分享大廚傳授的關鍵一步——「乾煸豆干至微焦起皮」，利用熱能排出豆干內多餘水分，使其表面形成微細孔洞，如此在紅燒收汁時便能迅速吸飽醬香精華，做出外Q內嫩、香氣撲鼻的極致鑊香美味。\n\n## 🥣 食材清單\n\n### 主料\n- 板豆腐干：4 塊（先橫剖薄片，再切成細絲）\n- 豬里脊肉絲：150 克\n- 蒜頭：4-5 瓣（切蒜片，約 20 克）\n- 紅辣椒：1 根（去籽切細絲，約 15 克）\n- 青蔥：2 根（切長蔥絲，約 30 克）\n\n### 🧂 肉絲嫩醃料\n- 醬油：1 茶匙\n- 米酒：1 大匙\n- 清水：1 大匙（抓水用）\n- 太白粉（生粉）：1 茶匙\n- 食用油：1 大匙（封油防黏用）\n\n### 🥣 調味醬汁\n- 醬油：2 大匙\n- 米酒：1 大匙\n- 清水：2 大匙\n- 砂糖：1 茶匙\n\n## 🍳 製作步驟\n\n1. **肉絲醃製（抓水與封油）**：\n   將豬肉絲放入碗中，加入醬油 1 茶匙、米酒 1 大匙、太白粉 1 茶匙與清水 1 大匙，用手用力抓勻，直到肉絲完全將水分吸乾（稱為「抓水」）。最後**加入食用油 1 大匙輕輕拌勻**（這能防止下鍋時肉絲黏在一起，並鎖住內部肉汁）。\n2. **大廚關鍵步：乾煸豆干（起皮入味）**：\n   熱鍋倒入 1 大匙食用油，放入切好的豆干絲，轉中火慢慢翻炒煸煎。持續煸炒 2 - 3 分鐘，直到豆干水分收乾，**表面呈現微微金黃起皺、略帶焦香**時，即可撥至鍋邊（或先盛出備用）。\n   > [!TIP]\n   > 這是豆干入味最關鍵的物理機制。豆干先乾煸至皮發皺，能排出豆干內多餘的游離水分，使其表皮收縮出類似油豆腐的微孔結構。這樣在後續加入醬汁時，豆干才能像海綿一樣迅速吸附調味料，味道才會香濃。\n3. **滑炒肉絲**：\n   原鍋利用餘油，放入醃好的肉絲，轉大火快速翻炒滑開，將肉絲炒至表面呈現白色且顆顆鬆散（約七分熟）。\n4. **爆香辛香料**：\n   將肉絲與豆干絲混和，放入蒜片、辣椒絲在鍋底爆香，快速翻炒出香氣。\n5. **熗鍋與煨燒**：\n   將調味醬汁（醬油 2 大匙、米酒 1 大匙、水 2 大匙、糖 1 茶匙）從鍋邊淋入，大火翻炒均勻，煨燒約 1 分鐘，直至湯汁被豆干絲完全吸乾收濃。\n6. **合蔥起鍋**：\n   最後撒入長蔥絲，快速大火翻炒 10 秒鐘至蔥絲斷生，即可關火盛盤，大口享用！",
