      "author": "2bentos_aweek",
      "source": "https://www.instagram.com/reel/DY0-6a6Sup5/",
      "ingredients": "這是一道超級下飯的台灣經典家常菜。將清脆甘甜的愛之味脆瓜切丁，與絞肉、脆瓜罐頭原汁及調味料攪拌至起膠，平鋪於盤中以電鍋蒸熟。蒸出來的肉餅鹹香油潤，帶著清甜的瓜香，連蒸出的湯汁都是拌飯的白飯殺手。 ## 食材 (2 人份) ## 調味料",
      "summary": "電鍋蒸瓜仔肉 這是一道超級下飯的台灣經典家常菜。將清脆甘甜的愛之味脆瓜切丁，與絞肉、脆瓜罐頭原汁及調味料攪拌至起膠，平鋪於盤中以電鍋蒸熟。蒸出來的肉餅鹹香油潤，帶著清甜的瓜香，連蒸出的湯汁都是拌飯的白飯殺手。 食材 2 人份 豬絞肉：1 盒 約 250g 300g 愛之味脆瓜：半罐 切成小碎丁 調味...",
      "content": "# 電鍋蒸瓜仔肉\n\n這是一道超級下飯的台灣經典家常菜。將清脆甘甜的愛之味脆瓜切丁，與絞肉、脆瓜罐頭原汁及調味料攪拌至起膠，平鋪於盤中以電鍋蒸熟。蒸出來的肉餅鹹香油潤，帶著清甜的瓜香，連蒸出的湯汁都是拌飯的白飯殺手。\n\n## 食材 (2 人份)\n\n*   豬絞肉：1 盒 (約 250g - 300g)\n*   愛之味脆瓜：半罐 (切成小碎丁)\n\n## 調味料\n\n*   醬油：1 大匙\n*   脆瓜罐頭原汁：1 大匙\n*   白胡椒粉：適量\n\n## 步驟\n\n1.  **切碎脆瓜**：將脆瓜取出切成小丁狀，罐頭內的脆瓜汁倒入小碗中留下一大匙備用。\n2.  **攪拌起膠**：將豬絞肉、切碎的脆瓜丁、醬油 1 大匙、脆瓜原汁 1 大匙與適量白胡椒粉全部放入大碗中。使用筷子朝同一個方向快速攪拌抓捏，直到絞肉產生黏性且邊緣出現白色毛邊（呈現起膠狀態）為止。*（註：攪拌出黏性能使肉餅定型，蒸的時候口感更彈牙且不散碎）*。\n3.  **鋪平壓實**：將攪拌好的肉餡倒入耐熱的深盤中，用湯匙背面均勻鋪平並稍微壓實。\n4.  **電鍋蒸熟**：放入電鍋中，外鍋加入 1 杯水（蒸煮時間約 20-30 分鐘）。待電鍋跳起後，燜 5 分鐘後即可取出趁熱享用。\n\n## 料理筆記\n\n*   脆瓜切小丁可以保留部分口感，攪拌時一定要朝同方向攪拌至起膠，肉質才會彈牙且有汁水。\n*   此道菜利用脆瓜罐頭汁的甘甜來調味，不需要額外加糖。若絞肉油脂偏少，可在攪拌肉餡時加入 1 小匙香油增添潤澤度。",
