      "author": "未知",
      "source": "https://www.instagram.com/reel/DVOGmKYD_Wc/?igsh=N2hvcGR0MGdwemNv",
      "ingredients": "### 主料\n- 小豆干：1200 公克",
      "summary": "電鍋黑糖滷豆干 原來豆干要入味好吃，又快又省力的撇步是用電鍋！這道電鍋黑糖滷豆干結合了乾辣椒、八角與黑糖的香氣，甜鹹交織，口感香 Q 彈牙。不論是當冷盤小菜、便當菜還是下午茶點心都非常適合。 🥣 食材清單 主料 小豆干：1200 公克 辛香料 乾辣椒：5 公克 八角：5 公克 薑片：15 公克 調味...",
      "content": "# 電鍋黑糖滷豆干\n\n原來豆干要入味好吃，又快又省力的撇步是用電鍋！這道電鍋黑糖滷豆干結合了乾辣椒、八角與黑糖的香氣，甜鹹交織，口感香 Q 彈牙。不論是當冷盤小菜、便當菜還是下午茶點心都非常適合。\n\n## 🥣 食材清單\n\n### 主料\n- 小豆干：1200 公克\n\n### 辛香料\n- 乾辣椒：5 公克\n- 八角：5 公克\n- 薑片：15 公克\n\n### 調味料\n- 油：50 毫升\n- 醬油：250 毫升\n- 黑糖：50 公克\n- 水：適量（能略淹過豆干的分量）\n\n## 🍳 製作步驟\n\n1. **汆燙豆干**：\n   小豆干洗淨後，放入滾水中汆燙去除豆腥味與多餘雜質，撈起瀝乾備用。\n2. **炒香滷汁**：\n   在電鍋內鍋中放入乾辣椒、八角、薑片，並加入油、醬油和黑糖。外鍋加入 1/2 杯水，按下開關加熱，將香料與醬汁炒出香氣。\n3. **放入豆干與加水**：\n   炒香後，將汆燙好的小豆干放入內鍋中，加入適量的水，水面需略淹過豆干。\n4. **電鍋慢滷**：\n   在電鍋外鍋加入 1 杯水，蓋上鍋蓋，煮至開關跳起後，**先不要開蓋，繼續燜泡入味**。\n5. **二次加熱（起鍋）**：\n   食用前，外鍋再加 1/2 杯水加熱至開關跳起，即可盛盤享用（亦可放涼後冰鎮食用，口感更 Q 彈）。\n\n## 💡 廚神小撇步\n- **熱水汆燙**：豆干一定要先汆燙過，除了衛生之外，也能讓豆干孔隙張開，後面更易吸附滷汁。\n- **燜泡的關鍵**：電鍋跳起後的「燜泡」是豆干入味卻不軟爛的核心技巧，讓豆干在滷汁中慢慢冷卻吸汁。\n- **冷藏食用更佳**：滷好後的豆干放入冰箱冷藏冰鎮一晚，黑糖與醬油的甜鹹香氣會更加濃郁，口感也會變得更加緊實 Q 彈。",
