      "ingredients": "### 主料\n* 全雞 1 隻（約 1 公斤，亦可使用 2–3 隻帶骨或去骨大雞腿）\n* 薑 1 塊（切厚片）\n* 青蔥 6–7 根（切長段與切蔥絲）\n* 食用油 1 大匙",
      "summary": "電飯煲無水蔥油雞 不加一滴水，利用電飯煲溫和緩慢加熱逼出雞肉自身的鮮甜雞汁！雞肉滑嫩多汁，起鍋後淋上香濃醬汁與熱油激發的蔥香，最後鍋底精華雞汁拌飯更是一絕。 🥣 食材清單 主料 全雞 1 隻（約 1 公斤，亦可使用 2–3 隻帶骨或去骨大雞腿） 薑 1 塊（切厚片） 青蔥 6–7 根（切長段與切蔥絲...",
      "content": "# 電飯煲無水蔥油雞\n\n不加一滴水，利用電飯煲溫和緩慢加熱逼出雞肉自身的鮮甜雞汁！雞肉滑嫩多汁，起鍋後淋上香濃醬汁與熱油激發的蔥香，最後鍋底精華雞汁拌飯更是一絕。\n\n## 🥣 食材清單\n\n### 主料\n* 全雞 1 隻（約 1 公斤，亦可使用 2–3 隻帶骨或去骨大雞腿）\n* 薑 1 塊（切厚片）\n* 青蔥 6–7 根（切長段與切蔥絲）\n* 食用油 1 大匙\n\n### 醃料\n* 鹽 1 小匙\n* 醬油 2 大匙\n* 米酒 1 大匙\n* 蠔油 1 大匙（可依喜好省略）\n* 白胡椒粉 適量\n\n### 起鍋淋醬\n* 醬油 2 小匙（或 2 大匙）\n* 熱油 1 大匙\n* 蔥絲 適量\n\n## 🍳 製作步驟\n\n1. **醃漬雞肉**：將雞洗淨後徹底擦乾水分。加入所有醃料（鹽、醬油、米酒、蠔油、白胡椒粉），均勻按摩全雞，醃製至少 1 小時（冷藏醃製隔夜更加入味）。\n2. **鍋底鋪料**：在電飯煲（電子鍋）底部鋪滿薑片與切段的蔥段，避免雞肉黏底並能去腥增香。\n3. **入鍋炊煮**：將醃好的雞肉放在薑蔥上方，並將盆內剩餘的醃汁全部倒入。按下煮飯鍵（標準行程約 45–60 分鐘）。\n4. **保溫燜熟**：程序結束跳起後，不要立刻開蓋，保持保溫狀態燜 30 分鐘，讓雞肉軟嫩熟透並鎖住水分。\n5. **淋醬潑油**：起鍋盛盤後，淋上醬油，鋪上新鮮蔥絲，將 1 大匙熱油燒熱後淋在蔥絲上激發香氣即完成。\n\n## 💡 廚神小撇步\n\n* **壓力鍋 / Instant Pot 作法**：若使用壓力鍋，選擇高壓模式（High Pressure）煮 25–30 分鐘，烹調完成後自然洩壓 10–15 分鐘，肉質一樣軟嫩多汁。\n* **精華雞汁應用**：鍋底留下的濃縮雞汁結合了蔥薑香氣與純雞精華，千萬不要倒掉，拿來拌白飯、拌麵或炒青菜都超級美味。",
