      "author": "未知",
      "source": "https://www.instagram.com/reel/Dbs8nTKpceT/",
      "ingredients": "### 主料\n* 豬梅花肉片（厚度約 1 公分） 300g\n* 新鮮青檸（黃檸檬亦可） 1 顆",
      "summary": "青檸芥末豬排 酸香開胃、層次豐富的特色豬排！梅花豬肉煎至金黃微焦，裹上蒜香蜂蜜芥末醬，最後擠入新鮮青檸汁與碎皮屑，酸甜交織解膩，10 分鐘就能快速輕鬆上桌。 🥣 食材清單 主料 豬梅花肉片（厚度約 1 公分） 300g 新鮮青檸（黃檸檬亦可） 1 顆 醃料 黑胡椒鹽 適量 調味料醬汁 蒜末 1 大匙...",
      "content": "# 青檸芥末豬排\n\n酸香開胃、層次豐富的特色豬排！梅花豬肉煎至金黃微焦，裹上蒜香蜂蜜芥末醬，最後擠入新鮮青檸汁與碎皮屑，酸甜交織解膩，10 分鐘就能快速輕鬆上桌。\n\n## 🥣 食材清單\n\n### 主料\n* 豬梅花肉片（厚度約 1 公分） 300g\n* 新鮮青檸（黃檸檬亦可） 1 顆\n\n### 醃料\n* 黑胡椒鹽 適量\n\n### 調味料醬汁\n* 蒜末 1 大匙\n* 薄鹽生抽（或淡色醬油） 1 大匙\n* 黃芥末醬 1.5 大匙\n* 蜂蜜 0.5 大匙\n* 食用油 少許\n\n## 🍳 製作步驟\n\n1. **醃製肉排**：梅花肉切成約 1 公分厚的肉排，兩面均勻撒上黑胡椒鹽，靜置醃製 10 分鐘。\n2. **煎香豬排**：起鍋加少許油（梅花肉本身油脂豐富），放入肉排煎至兩面呈金黃焦香感（每面約煎 3 分鐘），夾出稍微放涼後切成適口小塊備用。\n3. **爆香與調醬**：利用原鍋底油，放入蒜末小火炒出香氣，接著加入薄鹽生抽、黃芥末醬與蜂蜜，攪拌均勻燒至微微起泡。\n4. **裹醬與加檸檬**：將切塊的豬排倒回鍋中，快速翻炒讓醬汁均勻裹黏在豬排表面。關火出鍋前擠入新鮮青檸汁，並刨上少許青檸皮屑增添清爽香氣即可。\n\n## 💡 廚神小撇步\n\n* **選用梅花肉**：梅花肉油脂分佈均勻，煎過後香乾不柴；若選用里肌肉則建議先用肉錘打鬆。\n* **皮屑提香關鍵**：刨青檸皮屑時注意只刨綠色表皮層，不要刨到白色苦膜，能大大提升料理的精緻香氣與層次感。",
