      "author": "未知",
      "source": "https://www.instagram.com/reel/DcTM5bugats/",
      "ingredients": "### 主料\n* 小黃瓜 3–4 根",
      "summary": "韓式涼拌小黃瓜 夏天必備的清爽開胃神級小菜！爽脆多汁的小黃瓜裹上酸辣甜香的韓式特調醬汁，製作簡單快速，冰鎮後更是解膩爽口。 🥣 食材清單 主料 小黃瓜 3–4 根 萬用韓式涼拌醬汁 白芝麻 1 大匙 蒜末 2 大匙 韓式辣椒粉 2 大匙 蔥末 2 大匙 蠔油 2 大匙 糖（或阿洛酮糖） 4 大匙 辣...",
      "content": "# 韓式涼拌小黃瓜\n\n夏天必備的清爽開胃神級小菜！爽脆多汁的小黃瓜裹上酸辣甜香的韓式特調醬汁，製作簡單快速，冰鎮後更是解膩爽口。\n\n## 🥣 食材清單\n\n### 主料\n* 小黃瓜 3–4 根\n\n### 萬用韓式涼拌醬汁\n* 白芝麻 1 大匙\n* 蒜末 2 大匙\n* 韓式辣椒粉 2 大匙\n* 蔥末 2 大匙\n* 蠔油 2 大匙\n* 糖（或阿洛酮糖） 4 大匙\n* 辣椒油 4 大匙\n* 白醋（或果醋） 4 大匙\n* 醬油 6 大匙\n\n## 🍳 製作步驟\n\n1. **處理小黃瓜**：小黃瓜洗淨後瀝乾，用刀背拍裂後切成適口小段（拍裂更容易吸附醬汁）。\n2. **調製萬用醬汁**：將白芝麻、蒜末、辣椒粉、蔥末、蠔油、糖、辣椒油、醋與醬油置於碗中，攪拌均勻。\n3. **拌勻入味**：將切好的小黃瓜放入調理盆中，倒入調好的醬汁抓拌均勻。\n4. **冰鎮享用**：即可現吃，或放入保鮮盒密封冷藏 15–30 分鐘，冰涼脆口更加美味入味。\n\n## 💡 廚神小撇步\n\n* **拍黃瓜更入味**：用刀背輕拍小黃瓜使其產生自然裂紋，比起單純切片更能讓醬汁滲透入味。\n* **萬用醬汁多用途**：此韓式涼拌醬汁酸甜適中微辣，亦可用於涼拌木耳、蒟蒻麵、手撕雞肉或水豆腐。",
