      "author": "dustinwith",
      "source": "https://www.instagram.com/reel/DZj0jb9uoRA/",
      "ingredients": "*   大蝦仁：適量 (去殼、開背、去腸泥)\n*   鳳梨：適量 (切丁備用)",
      "summary": "鳳梨蝦球變奏版 蘋蘋無奇 這是一道經過改良的鳳梨蝦球。在傳統的美乃滋中調入新鮮蘋果泥與檸檬絲，大幅降低了傳統蝦球的油膩感，多了一股清爽的果香。醃蝦與粉漿的比例精確至公克，能確保炸出來的蝦球外酥內彈。 食材 大蝦仁：適量 去殼、開背、去腸泥 鳳梨：適量 切丁備用 醃蝦料 鹽與胡椒粉 黑白均可：共約 0...",
      "content": "# 鳳梨蝦球變奏版 (蘋蘋無奇)\n\n這是一道經過改良的鳳梨蝦球。在傳統的美乃滋中調入新鮮蘋果泥與檸檬絲，大幅降低了傳統蝦球的油膩感，多了一股清爽的果香。醃蝦與粉漿的比例精確至公克，能確保炸出來的蝦球外酥內彈。\n\n## 食材\n\n*   大蝦仁：適量 (去殼、開背、去腸泥)\n*   鳳梨：適量 (切丁備用)\n\n## 醃蝦料\n\n*   鹽與胡椒粉 (黑白均可)：共約 0.6 克\n*   米酒：4 克\n\n## 酥炸麵衣比例\n\n*   玉米粉：25 克\n*   吉士粉 (Custard Powder)：5 克 (增香增色的關鍵)\n*   蛋白 (蛋清)：20 克\n*   太白粉：適量 (外層乾粉用)\n\n## 蘋果美乃滋醬比例\n\n*   桂冠美乃滋 (建議使用 -40% 輕量版)：27 克\n*   新鮮蘋果泥：25 克\n*   檸檬絲：1 克\n*   新鮮檸檬汁：適量 (最後擠上)\n\n## 步驟\n\n1.  **醃漬與擦乾蝦球**：蝦仁開背洗淨。加入鹽和胡椒粉共 0.6 克、米酒 4 克輕輕抓勻，靜置醃漬數分鐘。接著用廚房紙巾將蝦球**完全擦乾**，使其表面帶有微微黏附紙巾的乾燥感（此步驟能確保炸粉緊密貼合不脫落）。\n2.  **調製濕粉漿**：在擦乾的蝦球中加入玉米粉 25 克、吉士粉 5 克、蛋白 20 克，用手反覆抓勻，使蝦球表面裹上均勻黏稠的糊狀粉漿。\n3.  **裹乾粉與油炸**：將裹好粉漿的蝦球逐一沾上乾太白粉，並輕輕拍掉多餘的粉以保持薄脆。放入預熱至 **170 度的油鍋中，油炸 40 秒**即可快速撈起、瀝油備用。\n4.  **調製蘋果美乃滋醬**：在一大碗中將美乃滋 27 克、新鮮蘋果泥 25 克、檸檬絲 1 克充分攪拌均勻。\n5.  **裹醬盛盤**：將炸好的蝦球放入碗中，與蘋果美乃滋醬快速拌勻，使每顆蝦球都裹上醬汁。盛盤並與鳳梨丁一同擺盤，最後在表面擠上少許新鮮檸檬汁即可享用。\n\n## 料理筆記\n\n*   吉士粉（起司粉/奶黃粉）能讓炸出來的蝦球呈現漂亮的金黃色，並帶有淡淡的奶香味，是讓鳳梨蝦球更具備餐館風味的秘訣。\n*   利用蘋果泥取代近乎一半的美乃滋，既能保持濃郁滑順的口感，又大大減輕了熱量負擔。",
