      "summary": "麻油高山娃娃菜 高山娃娃菜只有在冬末春初、天氣寒冷的高山上才種得出來，吃起來口感清脆、帶有淡淡的甜味。搭配溫潤的麻油與薑絲慢慢煸炒，再加入米酒與枸杞燜煮，做法簡單卻非常滋補養生，是寒冷季節裡不容錯過的美味時令小菜。 🥣 食材清單 主料 高山娃娃菜：約 300 克 薑：適量（切細絲） 枸杞：56 顆 ...",
      "content": "# 麻油高山娃娃菜\n\n高山娃娃菜只有在冬末春初、天氣寒冷的高山上才種得出來，吃起來口感清脆、帶有淡淡的甜味。搭配溫潤的麻油與薑絲慢慢煸炒，再加入米酒與枸杞燜煮，做法簡單卻非常滋補養生，是寒冷季節裡不容錯過的美味時令小菜。\n\n## 🥣 食材清單\n\n### 主料\n- 高山娃娃菜：約 300 克\n- 薑：適量（切細絲）\n- 枸杞：5-6 顆\n\n### 調味料\n- 麻油：2 大匙\n- 米酒：15 克\n- 水：約 50 毫升\n- 鹽巴：3 克\n\n## 🍳 製作步驟\n\n1. **食材準備**：\n   高山娃娃菜滾刀切成小塊；枸杞泡水軟化後瀝乾備用。\n2. **煸香薑絲**：\n   冷鍋下麻油，放入切好的薑絲，以**小火**慢慢煸炒出香氣（注意麻油不可大火炒，否則會變苦）。\n3. **下菜翻炒**：\n   倒入切好的高山娃娃菜，轉中火稍微翻炒均勻，讓娃娃菜表面都均勻裹上麻油。\n4. **燜煮入味**：\n   加入枸杞、米酒與水，蓋上鍋蓋，以**中火燜煮約 3-5 分鐘**，至娃娃菜變軟熟透。\n5. **調味收汁**：\n   打開鍋蓋，加入 3 克鹽巴調味，稍微翻炒均勻，待湯汁稍微收乾即完成。\n6. **點綴起鍋**：\n   盛盤後，可在表面再額外淋上一點點麻油，能讓香氣更加濃郁。\n\n## 💡 廚神小撇步\n- **冷鍋冷油煸薑**：麻油在過高溫度下會產生苦味。因此一定要在冷鍋時就倒入麻油，並用小火慢慢煸薑絲。\n- **滾刀切法**：娃娃菜使用滾刀切小塊，能讓菜塊在燜煮時更容易均勻受熱，且能保持清脆的口感。\n- **如何去苦味**：有的人會覺得娃娃菜的綠色部分帶有微苦。如果對苦味較敏感，可以在料理前將娃娃菜放入滾水中快速汆燙一遍，便能去除大部分苦味。",
